app/api/ai-review/route.ts.content:
import { NextRequest } from "next/server";
import { buildAiReview } from "@/lib/ai-review";
import { defaultReviewerModel, defaultScoutModel } from "@/lib/config";
import { githubFetch, githubJson, githubToken, jsonError, parsePullNumber, parseRepo } from "@/lib/github";
import { readSession } from "@/lib/session";
import type { PullRequestDetail } from "@/lib/types";

export const maxDuration = 120;

export async function POST(request: NextRequest) {
  try {
    const session = await readSession(request);
    if (!session.openrouter?.apiKey) throw new Error("OpenRouter authentication is required.");
    const token = await githubToken(request);
    const input = (await request.json()) as {
      repo?: string;
      number?: number;
      headSha?: string;
      scoutModel?: string;
      reviewerModel?: string;
    };
    const { fullName } = parseRepo(input.repo ?? null);
    const number = parsePullNumber(input.number);
    const scoutModel = input.scoutModel?.trim() || defaultScoutModel();
    const reviewerModel = input.reviewerModel?.trim() || defaultReviewerModel();
    const [pull, diffResponse] = await Promise.all([
      githubJson<{
        number: number;
        title: string;
        body: string | null;
        user: { login: string; avatar_url: string };
        base: { ref: string };
        head: { ref: string; sha: string };
      }>(token, `/repos/${fullName}/pulls/${number}`),
      githubFetch(token, `/repos/${fullName}/pulls/${number}`, {
        headers: { Accept: "application/vnd.github.v3.diff" },
      }),
    ]);
    if (input.headSha && pull.head.sha !== input.headSha) {
      throw new Error("This pull request changed before the AI review started. Refresh it and try again.");
    }
    const detail = {
      number: pull.number,
      title: pull.title,
      body: pull.body ?? "",
      author: { login: pull.user.login, avatarUrl: pull.user.avatar_url },
      base: pull.base.ref,
      head: pull.head.ref,
      diff: await diffResponse.text(),
    } as Pick<PullRequestDetail, "number" | "title" | "body" | "author" | "base" | "head" | "diff">;
    const review = await buildAiReview({
      repo: fullName,
      detail,
      apiKey: session.openrouter.apiKey,
      scoutModel,
      reviewerModel,
    });
    return Response.json({ review });
  } catch (error) {
    return jsonError(error);
  }
}

app/api/auth/github/callback/route.ts.content:
import { NextRequest, NextResponse } from "next/server";
import {
  appOrigin,
  clearTransaction,
  readSession,
  readTransaction,
  writeSession,
} from "@/lib/session";

export async function GET(request: NextRequest) {
  const transaction = await readTransaction(request);
  const code = request.nextUrl.searchParams.get("code");
  const state = request.nextUrl.searchParams.get("state");
  if (!transaction || transaction.provider !== "github" || !code || !state || state !== transaction.state) {
    return NextResponse.redirect(new URL("/?error=GitHub+authorization+could+not+be+verified", request.url));
  }
  try {
    const response = await fetch("https://github.com/login/oauth/access_token", {
      method: "POST",
      headers: { Accept: "application/json", "Content-Type": "application/json" },
      body: JSON.stringify({
        client_id: process.env.GITHUB_CLIENT_ID,
        client_secret: process.env.GITHUB_CLIENT_SECRET,
        code,
        code_verifier: transaction.verifier,
        redirect_uri: `${appOrigin(request)}/api/auth/github/callback`,
      }),
    });
    const token = (await response.json()) as {
      access_token?: string;
      refresh_token?: string;
      expires_in?: number;
      error_description?: string;
    };
    if (!response.ok || !token.access_token) throw new Error(token.error_description || "GitHub did not return an access token.");
    const viewerResponse = await fetch("https://api.github.com/user", {
      headers: {
        Accept: "application/vnd.github+json",
        Authorization: `Bearer ${token.access_token}`,
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "chronosphere",
      },
    });
    const viewer = (await viewerResponse.json()) as {
      login?: string;
      name?: string | null;
      avatar_url?: string;
      message?: string;
    };
    if (!viewerResponse.ok || !viewer.login) throw new Error(viewer.message || "GitHub user lookup failed.");
    const session = await readSession(request);
    session.github = {
      accessToken: token.access_token,
      refreshToken: token.refresh_token,
      expiresAt: token.expires_in ? Date.now() + token.expires_in * 1000 : undefined,
      login: viewer.login,
      name: viewer.name ?? null,
      avatarUrl: viewer.avatar_url ?? "",
    };
    const redirect = NextResponse.redirect(new URL("/", request.url));
    await writeSession(request, redirect, session);
    clearTransaction(request, redirect);
    return redirect;
  } catch (error) {
    const message = error instanceof Error ? error.message : "GitHub authorization failed.";
    return NextResponse.redirect(new URL(`/?error=${encodeURIComponent(message)}`, request.url));
  }
}

app/api/auth/github/route.ts.content:
import { NextRequest, NextResponse } from "next/server";
import { appOrigin, codeChallenge, randomToken, writeTransaction } from "@/lib/session";

export async function GET(request: NextRequest) {
  const clientId = process.env.GITHUB_CLIENT_ID;
  if (!clientId) {
    return NextResponse.redirect(new URL("/?error=GitHub+OAuth+is+not+configured", request.url));
  }
  const state = randomToken();
  const verifier = randomToken(48);
  const callback = `${appOrigin(request)}/api/auth/github/callback`;
  const url = new URL("https://github.com/login/oauth/authorize");
  url.searchParams.set("client_id", clientId);
  url.searchParams.set("redirect_uri", callback);
  url.searchParams.set("scope", "repo read:org");
  url.searchParams.set("state", state);
  url.searchParams.set("code_challenge", await codeChallenge(verifier));
  url.searchParams.set("code_challenge_method", "S256");
  const response = NextResponse.redirect(url);
  await writeTransaction(request, response, {
    provider: "github",
    state,
    verifier,
    expiresAt: Date.now() + 10 * 60 * 1000,
  });
  return response;
}

