}

app/api/auth/session/route.ts.content:
import { NextRequest } from "next/server";
import { defaultOpenRouterModel, defaultReviewerModel, defaultScoutModel } from "@/lib/config";
import { readSession } from "@/lib/session";

export async function GET(request: NextRequest) {
  const session = await readSession(request);
  return Response.json({
    github: session.github
      ? {
          connected: true,
          user: {
            login: session.github.login,
            name: session.github.name,
            avatarUrl: session.github.avatarUrl,
          },
        }
      : { connected: false, user: null },
    openrouter: {
      connected: Boolean(session.openrouter?.apiKey),
      userId: session.openrouter?.userId ?? null,
    },
    configured: {
      github: Boolean(process.env.GITHUB_CLIENT_ID && process.env.GITHUB_CLIENT_SECRET),
    },
    defaults: {
      model: defaultOpenRouterModel(),
      scoutModel: defaultScoutModel(),
      reviewerModel: defaultReviewerModel(),
    },
  });
}

app/api/github/file/route.ts.content:
import { NextRequest } from "next/server";
import { githubFetch, githubToken, jsonError, parseRepo } from "@/lib/github";

const MAX_CONTEXT_FILE_CHARS = 4_000_000;

function parsePath(value: string | null): string {
  const path = value?.trim() ?? "";
  const segments = path.split("/");
  if (!path || path.startsWith("/") || segments.some((segment) => !segment || segment === "." || segment === ".." || segment.includes("\0"))) {
    throw new Error("A valid repository file path is required.");
  }
  return segments.map(encodeURIComponent).join("/");
}

export async function GET(request: NextRequest) {
  try {
    const token = await githubToken(request);
    const { fullName } = parseRepo(request.nextUrl.searchParams.get("repo"));
    const ref = request.nextUrl.searchParams.get("ref")?.trim() ?? "";
    if (!/^[0-9a-f]{40}$/i.test(ref)) throw new Error("A valid commit SHA is required.");
    const path = parsePath(request.nextUrl.searchParams.get("path"));
    const response = await githubFetch(token, `/repos/${fullName}/contents/${path}?ref=${ref}`, {
      headers: { Accept: "application/vnd.github.raw+json" },
    });
    const content = await response.text();
    if (content.length > MAX_CONTEXT_FILE_CHARS) throw new Error("This file is too large to expand inline.");
    return Response.json({ content });
  } catch (error) {
    return jsonError(error);
  }
}

app/api/github/merge/route.ts.content:
import { NextRequest } from "next/server";
import { githubJson, githubToken, jsonError, parsePullNumber, parseRepo } from "@/lib/github";

export async function POST(request: NextRequest) {
  try {
    const token = await githubToken(request);
    const body = (await request.json()) as { repo?: string; number?: number; method?: string; sha?: string };
    const { fullName } = parseRepo(body.repo ?? null);
    const number = parsePullNumber(body.number);
    if (!['merge', 'squash', 'rebase'].includes(body.method ?? '')) throw new Error("Choose a valid merge method.");
    const result = await githubJson<{ merged: boolean; message: string; sha: string }>(token, `/repos/${fullName}/pulls/${number}/merge`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ merge_method: body.method, sha: body.sha }),
    });
    if (!result.merged) throw new Error(result.message || "GitHub did not merge the pull request.");
    return Response.json({ merge: result });
  } catch (error) {
    return jsonError(error);
  }
}

app/api/github/pull/route.ts.content:
import { NextRequest } from "next/server";
import { githubFetch, githubJson, githubToken, jsonError, parsePullNumber, parseRepo } from "@/lib/github";
import type { PullRequestDetail } from "@/lib/types";

interface GitHubPullDetail {
  number: number;
  title: string;
  body: string | null;
  html_url: string;
  state: "open" | "closed";
  merged: boolean;
  mergeable: boolean | null;
  mergeable_state: string;
  draft: boolean;
  created_at: string;
  updated_at: string;
  additions: number;
  deletions: number;
  changed_files: number;
  commits: number;
  user: { login: string; avatar_url: string };
  assignees: Array<{ login: string; avatar_url: string }>;
  requested_reviewers: Array<{ login: string; avatar_url: string }>;
  head: { ref: string; sha: string; repo: { full_name: string } | null };
  base: { ref: string; sha: string; repo: { full_name: string } | null };
}

interface RepoSettings {
  allow_merge_commit?: boolean;
  allow_squash_merge?: boolean;
  allow_rebase_merge?: boolean;
}

export async function GET(request: NextRequest) {
  try {
    const token = await githubToken(request);
    const { fullName } = parseRepo(request.nextUrl.searchParams.get("repo"));
    const number = parsePullNumber(request.nextUrl.searchParams.get("number"));
    const [pull, settings, diffResponse] = await Promise.all([
      githubJson<GitHubPullDetail>(token, `/repos/${fullName}/pulls/${number}`),
      githubJson<RepoSettings>(token, `/repos/${fullName}`).catch((): RepoSettings => ({})),
      githubFetch(token, `/repos/${fullName}/pulls/${number}`, {
        headers: { Accept: "application/vnd.github.v3.diff" },
      }),
    ]);
    const allowedMergeMethods: PullRequestDetail["allowedMergeMethods"] = [];
    if (settings.allow_merge_commit !== false) allowedMergeMethods.push("merge");
    if (settings.allow_squash_merge !== false) allowedMergeMethods.push("squash");
    if (settings.allow_rebase_merge !== false) allowedMergeMethods.push("rebase");
    const detail: PullRequestDetail = {
      number: pull.number,
      title: pull.title,
      body: pull.body ?? "",
      url: pull.html_url,
      state: pull.state,
      merged: pull.merged,
      mergeable: pull.mergeable,
      mergeableState: pull.mergeable_state,
      baseSha: pull.base.sha,
      headSha: pull.head.sha,
      baseRepo: pull.base.repo?.full_name ?? fullName,
      headRepo: pull.head.repo?.full_name ?? fullName,
      commits: pull.commits,
      author: { login: pull.user.login, avatarUrl: pull.user.avatar_url },
      assignees: pull.assignees.map((person) => ({ login: person.login, avatarUrl: person.avatar_url })),
      requestedReviewers: pull.requested_reviewers.map((person) => ({ login: person.login, avatarUrl: person.avatar_url })),
      draft: pull.draft,
      createdAt: pull.created_at,
      updatedAt: pull.updated_at,
      head: pull.head.ref,
      base: pull.base.ref,
      additions: pull.additions,
      deletions: pull.deletions,
      changedFiles: pull.changed_files,
      allowedMergeMethods,
      diff: await diffResponse.text(),
    };
    return Response.json({ pull: detail });
  } catch (error) {
    return jsonError(error);
  }
}

app/api/github/pulls/route.ts.content:
import { NextRequest } from "next/server";
import { githubGraphql, githubJson, githubToken, jsonError, parseRepo } from "@/lib/github";
import { PULL_SIZES_QUERY, applyPullSizes, pullSizeMap } from "@/lib/pull-sizes";
import type { PullRequestSummary } from "@/lib/types";

const PAGE_SIZE = 100;

interface GitHubPull {
  number: number;
  title: string;
  draft: boolean;
  created_at: string;
  updated_at: string;
  user: { login: string; avatar_url: string };
  assignees: Array<{ login: string; avatar_url: string }>;
  requested_reviewers: Array<{ login: string; avatar_url: string }>;
  head: { ref: string };
  base: { ref: string };
}

export async function GET(request: NextRequest) {
  try {
    const token = await githubToken(request);
    const { owner, repo, fullName } = parseRepo(request.nextUrl.searchParams.get("repo"));
    // Sizes are optional: a GraphQL failure leaves the rows without a size cluster.
    const [pulls, sizePayload] = await Promise.all([
      githubJson<GitHubPull[]>(token, `/repos/${fullName}/pulls?state=open&per_page=${PAGE_SIZE}&sort=updated&direction=desc`),
      githubGraphql<unknown>(token, PULL_SIZES_QUERY, { owner, repo, first: PAGE_SIZE }).catch(() => null),
    ]);
    const summaries: PullRequestSummary[] = pulls.map((pull) => ({
      number: pull.number,
      title: pull.title,
      author: { login: pull.user.login, avatarUrl: pull.user.avatar_url },
      assignees: pull.assignees.map((person) => ({ login: person.login, avatarUrl: person.avatar_url })),
      requestedReviewers: pull.requested_reviewers.map((person) => ({ login: person.login, avatarUrl: person.avatar_url })),
      draft: pull.draft,
      createdAt: pull.created_at,
      updatedAt: pull.updated_at,
      head: pull.head.ref,
      base: pull.base.ref,
      additions: 0,
      deletions: 0,
      changedFiles: 0,
    }));
    return Response.json({ pulls: applyPullSizes(summaries, pullSizeMap(sizePayload)) });
  } catch (error) {
    return jsonError(error);
  }
}

app/api/github/repos/route.ts.content:
import { NextRequest } from "next/server";
import { githubJson, githubToken, jsonError } from "@/lib/github";
import type { Repository } from "@/lib/types";

interface GitHubRepo {
  id: number;
  full_name: string;
  name: string;
  private: boolean;
  description: string | null;
  updated_at: string;
  owner: { login: string; avatar_url: string };
}

export async function GET(request: NextRequest) {
  try {
    const token = await githubToken(request);
    const repos = await githubJson<GitHubRepo[]>(
      token,
      "/user/repos?per_page=100&sort=pushed&direction=desc&affiliation=owner,collaborator,organization_member"
    );
    const result: Repository[] = repos.map((repo) => ({
      id: repo.id,
      fullName: repo.full_name,
      name: repo.name,
      owner: repo.owner.login,
      ownerAvatarUrl: repo.owner.avatar_url,
      private: repo.private,
      description: repo.description,
      updatedAt: repo.updated_at,
    }));
    return Response.json({ repositories: result });
  } catch (error) {
    return jsonError(error);
  }
}

app/api/github/review/route.ts.content:
import { NextRequest } from "next/server";
import { githubJson, githubToken, jsonError, parsePullNumber, parseRepo } from "@/lib/github";

export async function POST(request: NextRequest) {
  try {
    const token = await githubToken(request);
    const body = (await request.json()) as {
      repo?: string;
      number?: number;
      event?: string;
      body?: string;
      commitId?: string;
      comments?: Array<{ path?: string; line?: number; side?: string; body?: string }>;
    };
    const { fullName } = parseRepo(body.repo ?? null);
    const number = parsePullNumber(body.number);
    if (!['COMMENT', 'APPROVE', 'REQUEST_CHANGES'].includes(body.event ?? '')) throw new Error("Choose a valid review action.");
    const comments = (body.comments ?? []).map((comment) => {
      if (!comment.path || !Number.isInteger(comment.line) || !['LEFT', 'RIGHT'].includes(comment.side ?? '') || !comment.body?.trim()) {
        throw new Error("Every pending comment needs a valid diff line and message.");
      }
      return { path: comment.path, line: comment.line, side: comment.side, body: comment.body.trim() };
    });
    if (!comments.length && !body.body?.trim()) throw new Error("Add a summary or at least one pending comment.");
    const review = await githubJson<{ id: number; html_url: string }>(token, `/repos/${fullName}/pulls/${number}/reviews`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        body: body.body?.trim() ?? "",
        event: body.event,
        commit_id: body.commitId,
        comments,
      }),
    });
    return Response.json({ review: { id: review.id, url: review.html_url } });
  } catch (error) {
    return jsonError(error);
  }
}

app/api/replay/route.ts.content:
import { NextRequest } from "next/server";
import { githubFetch, githubJson, githubToken, jsonError, parsePullNumber, parseRepo } from "@/lib/github";
import { buildReplay, ReplayOutputError } from "@/lib/replay";
import { OpenRouterError, type ReplayStreamEvent } from "@/lib/replay-stream";
import { readSession } from "@/lib/session";
import type { PullRequestDetail } from "@/lib/types";

export const maxDuration = 120;

/** Roughly three progress events per second: alive to watch, cheap to send. */
const PROGRESS_INTERVAL_MS = 300;

/**
 * One JSON line per failure so Railway's log explorer can filter on the
 * fields. Everything OpenRouter told us travels along: status, code, provider,
 * raw upstream body, and the generation id to look the request up on their side.
 */
function logReplayFailure(error: unknown, context: { repo: string; number: number; model?: string; elapsedMs: number }) {
  const base = { level: "error", event: "replay.failed", ...context, error: error instanceof Error ? error.message : String(error) };
  const detail = error instanceof OpenRouterError
    ? { kind: "openrouter", ...error.details() }
    : error instanceof ReplayOutputError
      ? { kind: "model-output", output: error.snippet(), cause: error.cause instanceof Error ? error.cause.message : undefined, generationId: (error as { generationId?: string }).generationId }
      : { kind: error instanceof Error ? error.name : typeof error, generationId: (error as { generationId?: string })?.generationId, stack: error instanceof Error ? error.stack : undefined };
  console.error(JSON.stringify({ ...base, ...detail }));
}

export async function POST(request: NextRequest) {
  const startedAt = Date.now();
  let context: { repo: string; number: number; model?: string } | null = null;
  try {
    const session = await readSession(request);
    const apiKey = session.openrouter?.apiKey;
    if (!apiKey) throw new Error("OpenRouter authentication is required.");
    const token = await githubToken(request);
    const input = (await request.json()) as { repo?: string; number?: number; model?: string };
    const { fullName } = parseRepo(input.repo ?? null);
    const number = parsePullNumber(input.number);
    context = { repo: fullName, number, model: input.model?.trim() || undefined };
    const [pull, diffResponse] = await Promise.all([
      githubJson<{
        number: number; title: string; body: string | null;
        user: { login: string; avatar_url: string };
        base: { ref: string }; head: { ref: string };
      }>(token, `/repos/${fullName}/pulls/${number}`),
      githubFetch(token, `/repos/${fullName}/pulls/${number}`, { headers: { Accept: "application/vnd.github.v3.diff" } }),
    ]);
    const detail = {
      number: pull.number,
      title: pull.title,
      body: pull.body ?? "",
      author: { login: pull.user.login, avatarUrl: pull.user.avatar_url },
      base: pull.base.ref,
      head: pull.head.ref,
      diff: await diffResponse.text(),
    } as Pick<PullRequestDetail, "number" | "title" | "body" | "author" | "base" | "head" | "diff">;
    // Request validation and the GitHub round trip stay plain JSON errors; once
    // the model call begins the client is reading a stream, so build failures
    // travel as a terminal error event instead.
    const encoder = new TextEncoder();
    const stream = new ReadableStream<Uint8Array>({
      async start(controller) {
        let open = true;
        const send = (event: ReplayStreamEvent) => {
          if (!open) return;
          try {
            controller.enqueue(encoder.encode(`${JSON.stringify(event)}\n`));
          } catch {
            open = false; // The client hung up mid-build.
          }
        };
        let lastProgress = 0;
        try {
          const replay = await buildReplay(detail, apiKey, {
            model: input.model,
            signal: request.signal,
            onProgress: (chars) => {
              const now = Date.now();
              if (now - lastProgress < PROGRESS_INTERVAL_MS) return;
              lastProgress = now;
              send({ type: "progress", chars });
            },
            onParse: () => send({ type: "parsing" }),
          });
          send({ type: "done", replay });
        } catch (error) {
          logReplayFailure(error, { repo: fullName, number, model: input.model?.trim() || undefined, elapsedMs: Date.now() - startedAt });
          send({ type: "error", error: error instanceof Error ? error.message : "Could not build the replay." });
        } finally {
          try {
            if (open) controller.close();
          } catch {
            // Already closed by the client disconnecting.
          }
        }
      },
    });
    return new Response(stream, {
      headers: {
        "Content-Type": "application/x-ndjson; charset=utf-8",
        "Cache-Control": "no-store",
        "X-Accel-Buffering": "no",
      },
    });
  } catch (error) {
    // Validation and GitHub failures before the stream opens; the response
    // status says most of it, so log only what the client cannot show.
    console.warn(JSON.stringify({ level: "warn", event: "replay.rejected", ...context, error: error instanceof Error ? error.message : String(error) }));
    return jsonError(error);
  }
}

