.pr-main { min-width: 0; }
.pr-title-row { display: flex; align-items: center; gap: 8px; }
.pr-title-row strong { color: var(--ink); font-size: 13px; line-height: 1.4; }
.draft-badge { font-size: 10px; font-weight: 600; color: var(--muted); background: var(--surface-3); padding: 2px 6px; border-radius: var(--radius-sm); }
.pr-meta { flex-wrap: wrap; gap: 6px; margin-top: 6px; color: var(--faint); font-size: 11px; }
.people { gap: 5px; color: var(--muted); }
.avatar-stack { display: flex; }
.avatar-stack .avatar + .avatar { margin-left: -5px; border: 1px solid var(--surface); }
