.branch { display: flex; align-items: center; gap: 4px; margin-left: 6px; font-family: var(--font-mono), monospace; }
.pr-size { display: flex; align-items: center; gap: 8px; margin-left: 6px; color: var(--muted); font: 500 11px var(--font-mono), monospace; }
.pr-size .additions { color: var(--green); }
