.assignment-row { gap: 8px; flex-wrap: wrap; margin-top: 12px; color: var(--faint); font-size: 11px; }
.assignment-row > span:not(.people) { display: flex; align-items: center; gap: 4px; margin-left: 10px; }
.assignment-row > span:first-child { margin-left: 0; }

/* ============================================================================
   Replay: pull request header
   ========================================================================== */

.replay-shell { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.pr-header { height: 52px; flex: none; display: flex; align-items: center; gap: 16px; border-bottom: 1px solid var(--border); padding: 0 16px; background: var(--surface); }
.back-button { display: flex; align-items: center; gap: 6px; border: 0; background: transparent; color: var(--muted); font-size: 12px; cursor: pointer; padding: 6px; }
.back-button:hover { color: var(--ink); }
.pr-identity { min-width: 0; flex: 1; gap: 8px; }
.pr-identity strong { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 13px; }
.pr-identity > span:last-child { color: var(--faint); font: 500 12px var(--font-mono), monospace; }
.open-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--green-accent); box-shadow: 0 0 0 3px var(--green-soft); }
.pr-stats { gap: 12px; color: var(--muted); font: 500 11px var(--font-mono), monospace; }
.pr-stats .additions { color: var(--green); }
.pr-stats .deletions { color: var(--red); }
.pr-stats a { color: var(--accent); text-decoration: none; display: flex; align-items: center; gap: 4px; }

/* ============================================================================
   Replay: build screen
   ========================================================================== */

.build-replay { flex: 1; overflow-y: auto; display: flex; flex-direction: column; align-items: center; justify-content: safe center; text-align: center; padding: 48px 20px 72px; }
.build-replay h2 { margin: 14px 0 10px; font-size: 34px; letter-spacing: -0.035em; font-weight: 640; }
