.replay-illustration { width: 410px; max-width: 80vw; height: 100px; position: relative; margin-bottom: 24px; }
.orbit-line { position: absolute; top: 49px; left: 25px; right: 25px; height: 1px; background: var(--border-strong); }
.orbit-line::before { content: ""; position: absolute; left: 24%; right: 12%; height: 1px; background: var(--accent); }
.node { position: absolute; top: 34px; width: 32px; height: 32px; display: grid; place-items: center; border: 1px solid var(--border-strong); background: var(--surface); border-radius: 50%; font: 600 11px var(--font-mono), monospace; }
.n1 { left: 10px; }
.n2 { left: 31%; border-color: var(--accent-border); color: var(--accent); }
.n3 { left: 62%; border-color: var(--accent-border); color: var(--accent); }
