.ai-review-summary { margin: 10px 0; color: var(--ink); font-size: 12px; line-height: 1.55; white-space: pre-wrap; }
.ai-review-warning { border: 1px solid var(--amber-border); border-radius: var(--radius-sm); padding: 8px; background: var(--amber-soft); color: var(--amber); font-size: 11px; line-height: 1.45; }
.scout-details { margin: 10px 0 12px; border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 8px 10px; }
.scout-details summary { color: var(--muted); font: 600 11px var(--font-mono), monospace; cursor: pointer; }
.scout-details > p, .focus-area p { margin: 8px 0 0; color: var(--muted); font-size: 11px; line-height: 1.5; }
.focus-area { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 6px; margin-top: 8px; }
