import type { PullRequestSummary } from "./types";

/**
 * The REST pulls list omits size fields, so they come from one GraphQL call
 * that mirrors the REST page size and ordering and is joined on pull number.
 */
export interface PullSize {
  additions: number;
  deletions: number;
  changedFiles: number;
}

export const PULL_SIZES_QUERY = `query PullSizes($owner: String!, $repo: String!, $first: Int!) {
  repository(owner: $owner, name: $repo) {
    pullRequests(states: OPEN, first: $first, orderBy: { field: UPDATED_AT, direction: DESC }) {
      nodes { number additions deletions changedFiles }
    }
  }
}`;

function isCount(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

/** Tolerant read of the GraphQL payload; anything unexpected simply yields no size. */
export function pullSizeMap(payload: unknown): Map<number, PullSize> {
  const sizes = new Map<number, PullSize>();
  const nodes = (payload as { repository?: { pullRequests?: { nodes?: unknown } } } | null | undefined)
    ?.repository?.pullRequests?.nodes;
  if (!Array.isArray(nodes)) return sizes;
  for (const node of nodes) {
    if (!node || typeof node !== "object") continue;
    const { number: pullNumber, additions, deletions, changedFiles } = node as Record<string, unknown>;
    if (!isCount(pullNumber) || !isCount(additions) || !isCount(deletions) || !isCount(changedFiles)) continue;
    sizes.set(pullNumber, { additions, deletions, changedFiles });
  }
  return sizes;
}

/** Summaries keep their REST values wherever a size is missing. */
export function applyPullSizes(summaries: PullRequestSummary[], sizes: Map<number, PullSize>): PullRequestSummary[] {
  if (sizes.size === 0) return summaries;
  return summaries.map((summary) => {
    const size = sizes.get(summary.number);
    return size ? { ...summary, ...size } : summary;
  });
}

lib/recording.ts.content:
// Portable v1 format: one session line followed by ordered checkpoint events.
// A file replacement is a reversible patch; text and hashes travel together.
export const RECORDING_MAX_BYTES = 20 * 1024 * 1024;
export const RECORDING_MAX_EVENTS = 2000;
export const RECORDING_MAX_FILE_BYTES = 256 * 1024;

export interface RecordedFile { content: string; sha256: string }
export interface RecordedChange { path: string; before: RecordedFile | null; after: RecordedFile | null }
export interface RecordingSession {
  type: "session";
  format: "chronosphere.recording";
  version: 1;
  id: string;
  createdAt: string;
  title: string;
  capture: "checkpoints";
  repository: { name: string; head: string | null; branch: string | null };
  scope: string[];
  baseline: Record<string, RecordedFile>;
  omitted: Array<{ path: string; reason: string }>;
}
export interface RecordingEvent {
  type: "change" | "command" | "finish";
  id: string;
  sequence: number;
  recordedAt: string;
  title: string;
  reason: string;
  changes: RecordedChange[];
  omitted: Array<{ path: string; reason: string }>;
  command?: { argv: string[]; exitCode: number | null; signal: string | null; output: string; truncated: boolean };
}
export interface Recording { session: RecordingSession; events: RecordingEvent[] }

export async function contentHash(content: string): Promise<string> {
  const bytes = new TextEncoder().encode(content);
  const digest = await globalThis.crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

function object(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("Expected a recording object.");
  return value as Record<string, unknown>;
}
function string(value: unknown, max = 8000): asserts value is string {
  if (typeof value !== "string" || !value.trim() || value.length > max) throw new Error("Missing or invalid recording text.");
}
function path(value: unknown): asserts value is string {
  string(value, 4096);
  if (value.startsWith("/") || value.includes("\\") || value.split("/").some((part) => !part || part === ".." || part === ".") || /[\x00-\x1f]/.test(value)) throw new Error("Invalid recording file path.");
}
function timestamp(value: unknown) {
  string(value, 100);
  if (!Number.isFinite(Date.parse(value))) throw new Error("Invalid recording timestamp.");
}
function omissions(value: unknown) {
  if (!Array.isArray(value) || value.length > 10000) throw new Error("Invalid omitted-file list.");
  for (const item of value) { const entry = object(item); path(entry.path); string(entry.reason); }
}
function same(a: RecordedFile | null, b: RecordedFile | null) {
  return a === null ? b === null : b !== null && a.sha256 === b.sha256 && a.content === b.content;
}

/** Validate untrusted imports, including every content hash and patch precondition. */
export async function parseRecording(source: string): Promise<Recording> {
  if (new TextEncoder().encode(source).length > RECORDING_MAX_BYTES) throw new Error("Recording exceeds the 20 MB import limit.");
  const lines = source.trimEnd().split("\n");
  if (lines.length > RECORDING_MAX_EVENTS + 1) throw new Error("Recording has too many events.");
  let records: unknown[];
  try { records = lines.map((line) => JSON.parse(line)); }
  catch { throw new Error("Invalid JSONL recording. A line may be incomplete; use the original recording file."); }
  const header = object(records[0]);
  if (header.type !== "session" || header.format !== "chronosphere.recording" || header.version !== 1 || header.capture !== "checkpoints") throw new Error("Unsupported recording format. Expected Chronosphere recording v1.");
  string(header.id); string(header.title); timestamp(header.createdAt);
  const repo = object(header.repository);
  string(repo.name);
  for (const field of [repo.head, repo.branch]) if (field !== null) string(field);
  if (!Array.isArray(header.scope) || !header.scope.length) throw new Error("Missing recording scope.");
  for (const entry of header.scope) { if (entry !== ".") path(entry); }
  omissions(header.omitted);
  const seenHashes = new Map<string, string>();
  async function file(value: unknown): Promise<RecordedFile | null> {
    if (value === null) return null;
    const data = object(value);
    if (typeof data.content !== "string" || new TextEncoder().encode(data.content).length > RECORDING_MAX_FILE_BYTES || typeof data.sha256 !== "string" || !/^[a-f0-9]{64}$/.test(data.sha256)) throw new Error("Invalid recorded file.");
    if (seenHashes.get(data.sha256) !== data.content && await contentHash(data.content) !== data.sha256) throw new Error("Recording content hash does not match its text.");
    seenHashes.set(data.sha256, data.content);
    return { content: data.content, sha256: data.sha256 };
  }
  const state = new Map<string, RecordedFile>();
  const baseline = object(header.baseline);
  for (const [name, value] of Object.entries(baseline)) {
    path(name);
    const data = await file(value);
    if (!data) throw new Error("Baseline files cannot be null.");
    state.set(name, data);
  }
  const ids = new Set<string>([header.id]);
  let finished = false;
  for (let index = 1; index < records.length; index++) {
    const entry = object(records[index]);
    if (finished || !["change", "command", "finish"].includes(entry.type as string) || entry.sequence !== index) throw new Error("Recording events are missing, reordered, or follow a finished session.");
    string(entry.id); string(entry.title); string(entry.reason); timestamp(entry.recordedAt); omissions(entry.omitted);
    if (ids.has(entry.id)) throw new Error("Duplicate recording event ID.");
    ids.add(entry.id);
    if (!Array.isArray(entry.changes)) throw new Error("Missing event changes.");
    const touched = new Set<string>();
    for (const raw of entry.changes) {
      const change = object(raw);
      path(change.path);
      if (touched.has(change.path)) throw new Error("Duplicate file in a checkpoint.");
      touched.add(change.path);
      const before = await file(change.before), after = await file(change.after);
      if (!same(state.get(change.path) ?? null, before)) throw new Error(`Patch does not match prior state: ${change.path}`);
      if (same(before, after)) throw new Error("Recording contains an empty file change.");
      if (after) state.set(change.path, after); else state.delete(change.path);
    }
    if (entry.type === "command") {
      const command = object(entry.command);
      if (!Array.isArray(command.argv) || !command.argv.length || !command.argv.every((arg) => typeof arg === "string") || !(command.exitCode === null || Number.isInteger(command.exitCode)) || !(command.signal === null || typeof command.signal === "string") || typeof command.output !== "string" || command.output.length > 40000 || typeof command.truncated !== "boolean") throw new Error("Invalid command result.");
    } else if (entry.command !== undefined) throw new Error("Unexpected command result.");
    finished = entry.type === "finish";
  }
  return { session: header as unknown as RecordingSession, events: records.slice(1) as RecordingEvent[] };
}

/** Index zero is the baseline; later indexes include that many events. */
export function recordingStateAt(recording: Recording, index: number): Map<string, RecordedFile> {
  const state = new Map(Object.entries(recording.session.baseline));
  for (const event of recording.events.slice(0, Math.max(0, index))) {
    for (const change of event.changes) {
      if (change.after) state.set(change.path, change.after); else state.delete(change.path);
    }
  }
  return state;
}

lib/replay-stream.ts.content:
import type { ReplayResult } from "./types";

/**
 * Newline-delimited JSON events streamed by POST /api/replay.
 *
 * The server emits throttled `progress` events while the model output
 * accumulates, one `parsing` event once the output is complete and the steps
 * are being ordered, and exactly one terminal `done` or `error` event.
 */
export type ReplayStreamEvent =
  | { type: "progress"; chars: number }
  | { type: "parsing" }
  | { type: "done"; replay: ReplayResult }
  | { type: "error"; error: string };

/** One frame of an OpenRouter server-sent event stream. */
export type OpenRouterFrame = { content: string } | { error: OpenRouterError };

/** Diagnostic fields OpenRouter attaches to an error, before or mid-stream. */
export interface OpenRouterErrorDetails {
  /** HTTP status of a non-2xx response; absent for mid-stream error frames. */
  status?: number;
  /** OpenRouter's own error code, numeric or symbolic (e.g. 500, "server_error"). */
  code?: string | number;
  /** Upstream provider that failed, when OpenRouter names one. */
  provider?: string;
  /** Raw upstream error body, when OpenRouter forwards one. */
  raw?: string;
  /** X-Generation-Id of the request, for correlating with OpenRouter's logs. */
  generationId?: string;
}

/** Longest raw upstream error kept in the user-facing message. */
const RAW_SNIPPET_CHARS = 200;

function asText(value: unknown): string | undefined {
  if (value === undefined || value === null || value === "") return undefined;
  return typeof value === "string" ? value : JSON.stringify(value);
}

/**
 * An OpenRouter failure with its diagnostic fields kept alongside the message,
 * so the route can log the whole picture instead of one sentence.
 */
export class OpenRouterError extends Error {
  readonly status?: number;
  readonly code?: string | number;
  readonly provider?: string;
  readonly raw?: string;
  generationId?: string;

  constructor(message: string | undefined, details: OpenRouterErrorDetails = {}) {
    super(describeOpenRouterError(message, details));
    this.name = "OpenRouterError";
    this.status = details.status;
    this.code = details.code;
    this.provider = details.provider;
    this.raw = details.raw;
    this.generationId = details.generationId;
  }

  /** Flat, JSON-safe view of the failure for structured logs. */
  details(): Record<string, string | number | undefined> {
    return { message: this.message, status: this.status, code: this.code, provider: this.provider, raw: this.raw, generationId: this.generationId };
  }
}

/** Builds the user-facing sentence: the message, then whatever OpenRouter blamed. */
export function describeOpenRouterError(message: string | undefined, details: OpenRouterErrorDetails = {}): string {
  const own = !message?.trim();
  const base = message?.trim() || (details.status ? `OpenRouter returned ${details.status}` : "OpenRouter reported an error mid-stream");
  const blame = [details.provider, details.code !== undefined && String(details.code) !== String(details.status) ? `code ${details.code}` : undefined].filter(Boolean).join(", ");
  const raw = details.raw && details.raw !== message
    ? details.raw.length > RAW_SNIPPET_CHARS ? `${details.raw.slice(0, RAW_SNIPPET_CHARS)}…` : details.raw
    : undefined;
  const tail = `${blame ? ` (${blame})` : ""}${raw ? `: ${raw}` : ""}`;
  // OpenRouter's own sentences are passed through untouched; ours get a full stop.
  return own && !tail ? `${base}.` : `${base}${tail}`;
}

/** The shape OpenRouter uses for error payloads, both plain JSON and SSE frames. */
export interface OpenRouterErrorPayload {
  error?: { message?: string; code?: string | number; metadata?: { raw?: unknown; provider_name?: string } } | string;
}

/** Reads OpenRouter's error object into an OpenRouterError; null when the payload has none. */
export function openRouterError(payload: OpenRouterErrorPayload | null | undefined, details: OpenRouterErrorDetails = {}): OpenRouterError | null {
  const error = payload?.error;
  if (!error) return null;
  if (typeof error === "string") return new OpenRouterError(error, details);
  return new OpenRouterError(error.message, {
    ...details,
    code: error.code ?? details.code,
    provider: error.metadata?.provider_name ?? details.provider,
    raw: asText(error.metadata?.raw) ?? details.raw,
  });
}

/** Buffers decoded text and releases only the lines that are complete. */
export function lineBuffer() {
  let pending = "";
  return {
    push(text: string): string[] {
      pending += text;
      const lines = pending.split("\n");
      pending = lines.pop() ?? "";
      return lines;
    },
    flush(): string[] {
      const rest = pending;
      pending = "";
      return rest ? [rest] : [];
    },
  };
}

async function* decode(body: ReadableStream<Uint8Array>): AsyncGenerator<string> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      yield decoder.decode(value, { stream: true });
    }
    const tail = decoder.decode();
    if (tail) yield tail;
  } finally {
    reader.releaseLock();
  }
}

/**
 * Reads one OpenRouter SSE line. Returns null for keep-alive comments, the
 * `[DONE]` sentinel, and frames that carry no content.
 */
export function openRouterFrame(line: string): OpenRouterFrame | null {
  const trimmed = line.trim();
  if (!trimmed.startsWith("data:")) return null;
  const payload = trimmed.slice("data:".length).trim();
  if (!payload || payload === "[DONE]") return null;
  let parsed: OpenRouterErrorPayload & {
    choices?: Array<{ delta?: { content?: string | null } }>;
    provider?: string;
  };
  try {
    parsed = JSON.parse(payload) as typeof parsed;
  } catch {
    return null;
  }
  const error = openRouterError(parsed, { provider: parsed.provider });
  if (error) return { error };
  const content = parsed.choices?.[0]?.delta?.content;
  return content ? { content } : null;
}

/** Yields the content deltas of an OpenRouter stream, throwing on an error frame. */
export async function* readOpenRouterContent(body: ReadableStream<Uint8Array>): AsyncGenerator<string> {
  const lines = lineBuffer();
  const emit = function* (line: string): Generator<string> {
    const frame = openRouterFrame(line);
    if (!frame) return;
    if ("error" in frame) throw frame.error;
    yield frame.content;
  };
  for await (const text of decode(body)) {
    for (const line of lines.push(text)) yield* emit(line);
  }
  for (const line of lines.flush()) yield* emit(line);
}

/** Reads one newline-delimited replay event, ignoring blank or unrecognised lines. */
export function parseReplayEvent(line: string): ReplayStreamEvent | null {
  const trimmed = line.trim();
  if (!trimmed) return null;
  let parsed: Partial<ReplayStreamEvent> & { chars?: unknown; error?: unknown; replay?: unknown };
  try {
    parsed = JSON.parse(trimmed) as typeof parsed;
  } catch {
    return null;
  }
  if (parsed.type === "progress" && typeof parsed.chars === "number") return { type: "progress", chars: parsed.chars };
  if (parsed.type === "parsing") return { type: "parsing" };
  if (parsed.type === "done" && parsed.replay) return { type: "done", replay: parsed.replay as ReplayResult };
  if (parsed.type === "error") {
    return { type: "error", error: typeof parsed.error === "string" ? parsed.error : "Could not build the replay." };
  }
  return null;
}

/** Yields the replay events carried by a POST /api/replay response body. */
export async function* readReplayEvents(body: ReadableStream<Uint8Array>): AsyncGenerator<ReplayStreamEvent> {
  const lines = lineBuffer();
  for await (const text of decode(body)) {
    for (const line of lines.push(text)) {
      const event = parseReplayEvent(line);
      if (event) yield event;
    }
  }
  for (const line of lines.flush()) {
    const event = parseReplayEvent(line);
    if (event) yield event;
  }
}

