import { changedLines, normalizeReplayChunks, parseUnifiedDiff, type RawReplayChunk } from "./diff";
import { defaultOpenRouterModel } from "./config";
import { OpenRouterError, openRouterError, type OpenRouterErrorPayload, readOpenRouterContent } from "./replay-stream";
import type { PullRequestDetail, ReplayResult } from "./types";

const MAX_LISTING_CHARS = 280_000;

const SYSTEM_PROMPT = `You reconstruct how a pull request might have been written so a reviewer can watch the work land step by step instead of reading one wall of diff.

Divide every numbered changed line into coherent steps and order them as a plausible implementation sequence: foundations and types first, then core logic, then callers and UI, then tests and documentation. The real order is unknown; choose the order that is easiest to understand.

Rules:
- Prefer fewer, larger steps. Each step should be a complete unit of work a reviewer can hold in their head — typically 50–250 changed lines in total, and never much more than 250; past that a step becomes mentally heavy.
- Do not fragment the diff into a long run of tiny steps: fold small mechanical changes (imports, renames, wiring, config) into the step they support rather than giving each its own step. A step may fall below the range only when the whole diff is small or a change genuinely stands alone.
- A step is a list of ranges. Each range must be one contiguous [start, end] run of numbered lines within a single file, but one step may hold several ranges from different files when they are one unit of work: a trait or interface together with its implementation, a type together with the code that first uses it, a function together with its test. Do not combine unrelated changes just because they are small.
- Never split a statement or block just to fit a size target.
- Cover every numbered line exactly once across all ranges: no gaps and no overlaps.
- Deleted lines are numbered too and belong with the step that removes or replaces them.
- Narrate what the code does in plain language. Do not review, judge, or invent intent.
- Mark only the few most consequential steps as impactful: steps that establish a central behavior or contract, affect many downstream callers, or carry notable correctness or security consequences. Most steps should be false.
- Return only JSON matching: {"chunks":[{"ranges":[{"start":1,"end":3},{"start":40,"end":52}],"title":"Short title","description":"One or two sentences.","impactful":true}]}`;

function listing(diff: string): { text: string; truncated: boolean } {
  const files = parseUnifiedDiff(diff);
  let output = "";
  let truncated = false;
  for (const file of files) {
    const header = `\n== ${file.path} (${file.status})\n`;
    if (output.length + header.length > MAX_LISTING_CHARS) {
      truncated = true;
      break;
    }
    output += header;
    for (const hunk of file.hunks) {
      const lines = [hunk.header, ...hunk.lines.map((line) => {
        if (line.type === "context") return `       ${line.text}`;
        return `[${line.changedIndex}] ${line.type === "add" ? "+" : "-"} ${line.text}`;
      })];
      for (const line of lines) {
        if (output.length + line.length + 1 > MAX_LISTING_CHARS) {
          truncated = true;
          break;
        }
        output += `${line}\n`;
      }
      if (truncated) break;
    }
    if (truncated) break;
  }
  return { text: output.trim(), truncated };
}

/** Longest slice of model output kept when reporting unparseable JSON. */
const OUTPUT_SNIPPET_CHARS = 400;

/** Thrown when the model's output is not the JSON the prompt asked for. */
export class ReplayOutputError extends Error {
  constructor(message: string, readonly output: string, readonly cause?: unknown) {
    super(message);
    this.name = "ReplayOutputError";
  }

  /** Head and tail of the offending output, for logs. */
  snippet(): string {
    if (this.output.length <= OUTPUT_SNIPPET_CHARS) return this.output;
    const half = OUTPUT_SNIPPET_CHARS / 2;
    return `${this.output.slice(0, half)} … ${this.output.slice(-half)}`;
  }
}

function parseModelJson(content: string): { chunks?: unknown[] } {
  const fenced = content.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1];
  const candidate = fenced ?? content.slice(content.indexOf("{"), content.lastIndexOf("}") + 1);
  try {
    return JSON.parse(candidate) as { chunks?: unknown[] };
  } catch (cause) {
    throw new ReplayOutputError("The model returned a replay that was not valid JSON.", content, cause);
  }
}

export interface BuildReplayOptions {
  /** OpenRouter model slug; falls back to the configured default. */
  model?: string;
  /** Aborts the model call when the caller goes away. */
  signal?: AbortSignal;
  /** Called with the accumulated model output length as content streams in. */
  onProgress?: (chars: number) => void;
  /** Called once the model output is complete and the steps are being ordered. */
  onParse?: () => void;
}

export async function buildReplay(
  detail: Pick<PullRequestDetail, "number" | "title" | "body" | "author" | "base" | "head" | "diff">,
  apiKey: string,
  options: BuildReplayOptions = {}
): Promise<ReplayResult> {
  const files = parseUnifiedDiff(detail.diff);
  const total = changedLines(files).length;
  if (total === 0) throw new Error("This pull request has no textual changes to replay.");
  const numbered = listing(detail.diff);
  const model = options.model?.trim() || defaultOpenRouterModel();
  const prompt = `PR #${detail.number}: ${detail.title}\nBase: ${detail.base}  Head: ${detail.head}  Author: @${detail.author.login}\n\nDescription:\n${detail.body || "(no description)"}\n\nChanged lines, numbered:\n${numbered.text}`;
  const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
    method: "POST",
    signal: options.signal,
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
      "HTTP-Referer": process.env.APP_URL || "http://localhost:3000",
      "X-Title": "Chronosphere",
    },
    body: JSON.stringify({
      model,
      temperature: 0.2,
      stream: true,
      response_format: { type: "json_object" },
      messages: [
        { role: "system", content: SYSTEM_PROMPT },
        { role: "user", content: prompt },
      ],
    }),
  });
  const generationId = response.headers.get("x-generation-id") ?? undefined;
  if (!response.ok) {
    // OpenRouter reports bad models and bad keys as a JSON body, streaming or
    // not; when the body is not JSON, keep it raw so the log still shows it.
    const text = await response.text().catch(() => "");
    let payload: OpenRouterErrorPayload | null = null;
    try {
      payload = JSON.parse(text) as typeof payload;
    } catch {
      payload = null;
    }
    const details = { status: response.status, generationId, raw: payload ? undefined : text.trim() || undefined };
    throw openRouterError(payload, details) ?? new OpenRouterError(undefined, details);
  }
  if (!response.body) throw new OpenRouterError("OpenRouter returned an empty replay.", { generationId });
  try {
    let content = "";
    for await (const delta of readOpenRouterContent(response.body)) {
      content += delta;
      options.onProgress?.(content.length);
    }
    if (!content) throw new OpenRouterError("OpenRouter returned an empty replay.", { generationId });
    options.onParse?.();
    const parsed = parseModelJson(content);
    const chunks = normalizeReplayChunks((parsed.chunks ?? []) as RawReplayChunk[], files);
    if (!chunks.length) throw new ReplayOutputError("The model did not return any usable replay steps.", content);
    return { model, chunks, truncated: numbered.truncated };
  } catch (error) {
    // Anything that fails after the model call started belongs to this generation.
    if (error instanceof Error && !(error as { generationId?: string }).generationId) Object.assign(error, { generationId });
    throw error;
  }
}

lib/repo-recency.ts.content:
import type { Repository } from "./types";

/** Per-browser record of when each repository was last opened in the picker. */
export type RepoRecency = Record<string, number>;

export const REPO_RECENCY_KEY = "chronosphere:repo-recency";
const RECENCY_LIMIT = 50;

export function loadRepoRecency(storage: Storage | null): RepoRecency {
  if (!storage) return {};
  try {
    const raw = storage.getItem(REPO_RECENCY_KEY);
    if (!raw) return {};
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    const recency: RepoRecency = {};
    for (const [fullName, openedAt] of Object.entries(parsed as Record<string, unknown>)) {
      if (typeof openedAt === "number" && Number.isFinite(openedAt)) recency[fullName] = openedAt;
    }
    return recency;
  } catch {
    // Storage may be unavailable or hold unparsable data.
    return {};
  }
}

/** Records an open and prunes the oldest entries past the cap. */
export function recordRepoOpened(storage: Storage | null, fullName: string, openedAt = Date.now()): RepoRecency {
  const merged = { ...loadRepoRecency(storage), [fullName]: openedAt };
  const kept = Object.entries(merged).sort((a, b) => b[1] - a[1]).slice(0, RECENCY_LIMIT);
  const recency: RepoRecency = Object.fromEntries(kept);
  try {
    storage?.setItem(REPO_RECENCY_KEY, JSON.stringify(recency));
  } catch {
    // Storage may be unavailable; recency is a convenience, not a requirement.
  }
  return recency;
}

/** Most recently opened first, then everything else in the order the API returned. */
export function orderByRecency(repositories: Repository[], recency: RepoRecency): Repository[] {
  const recent = repositories.filter((repo) => recency[repo.fullName] !== undefined);
  if (recent.length === 0) return repositories;
  recent.sort((a, b) => recency[b.fullName] - recency[a.fullName]);
  return [...recent, ...repositories.filter((repo) => recency[repo.fullName] === undefined)];
}

lib/review-cache.ts.content:
import type { AiReviewResult, PendingComment, ReplayChunk, ReplayRange, ReplayResult } from "./types";

export type ReviewEvent = "COMMENT" | "APPROVE" | "REQUEST_CHANGES";

export interface InProgressReview {
  headSha: string;
  replay: ReplayResult;
  step: number;
  comments: PendingComment[];
  summary: string;
  event: ReviewEvent;
  model: string;
  showFullDiff: boolean;
  aiReview?: AiReviewResult;
  scoutModel?: string;
  reviewerModel?: string;
}

type StoredReview = InProgressReview & {
  version: 1;
  updatedAt: number;
};

const CACHE_PREFIX = "chronosphere-review:v1";

export function reviewCacheKey(viewer: string, repo: string, pullNumber: number): string {
  return `${CACHE_PREFIX}:${encodeURIComponent(viewer.toLowerCase())}:${encodeURIComponent(repo.toLowerCase())}:${pullNumber}`;
}

export function isReviewEvent(value: unknown): value is ReviewEvent {
  return value === "COMMENT" || value === "APPROVE" || value === "REQUEST_CHANGES";
}

function isReplayRange(value: unknown): value is ReplayRange {
  if (!value || typeof value !== "object") return false;
  const range = value as Partial<ReplayRange>;
  return typeof range.file === "string"
    && Number.isInteger(range.start)
    && (range.start as number) >= 0
    && Number.isInteger(range.end)
    && (range.end as number) >= (range.start as number);
}

/** The single-range step shape stored before steps could span files. */
type LegacyReplayChunk = Omit<ReplayChunk, "ranges"> & ReplayRange;

function isReplayChunk(value: unknown): value is ReplayChunk | LegacyReplayChunk {
  if (!value || typeof value !== "object") return false;
  const chunk = value as Partial<ReplayChunk> & Partial<ReplayRange>;
  const coverage = Array.isArray(chunk.ranges)
    ? chunk.ranges.length > 0 && chunk.ranges.every(isReplayRange)
    : isReplayRange(chunk);
  return coverage
    && typeof chunk.title === "string"
    && typeof chunk.description === "string"
    && (chunk.impactful === undefined || typeof chunk.impactful === "boolean");
}

/** Accepts replays stored in either the current or the legacy single-range step shape. */
export function isReplay(value: unknown): value is ReplayResult {
  if (!value || typeof value !== "object") return false;
  const replay = value as Partial<ReplayResult>;
  return typeof replay.model === "string"
    && typeof replay.truncated === "boolean"
    && Array.isArray(replay.chunks)
    && replay.chunks.length > 0
    && replay.chunks.every(isReplayChunk);
}

/** Rewrites legacy single-range steps into the current multi-range shape. */
export function upgradeReplay(replay: ReplayResult): ReplayResult {
  const chunks = (replay.chunks as Array<ReplayChunk | LegacyReplayChunk>).map((chunk): ReplayChunk => {
    if ("ranges" in chunk && Array.isArray(chunk.ranges)) return chunk;
    const { file, start, end, ...rest } = chunk as LegacyReplayChunk;
    return { ...rest, ranges: [{ file, start, end }] };
  });
  return chunks.every((chunk, index) => chunk === replay.chunks[index]) ? replay : { ...replay, chunks };
}

export function isPendingComment(value: unknown): value is PendingComment {
  if (!value || typeof value !== "object") return false;
  const comment = value as Partial<PendingComment>;
  return typeof comment.id === "string"
    && typeof comment.path === "string"
    && typeof comment.line === "number"
    && Number.isInteger(comment.line)
    && comment.line > 0
    && (comment.side === "LEFT" || comment.side === "RIGHT")
    && typeof comment.body === "string"
    && typeof comment.step === "number"
    && Number.isInteger(comment.step)
    && comment.step >= 0;
}

export function isAiReview(value: unknown): value is AiReviewResult {
  if (!value || typeof value !== "object") return false;
  const review = value as Partial<AiReviewResult>;
  const severities = new Set(["critical", "high", "medium", "low"]);
  const categories = new Set(["bug", "security", "performance", "correctness", "design", "test"]);
  const risks = new Set(["high", "medium", "low"]);
  return typeof review.scoutModel === "string"
    && typeof review.reviewerModel === "string"
    && typeof review.summary === "string"
    && typeof review.truncated === "boolean"
    && !!review.scout
    && typeof review.scout.intent === "string"
    && Array.isArray(review.scout.focusAreas)
    && review.scout.focusAreas.every((area) => !!area
      && typeof area.file === "string"
      && typeof area.reason === "string"
      && risks.has(area.risk))
    && Array.isArray(review.findings)
    && review.findings.every((finding) => !!finding
      && typeof finding.file === "string"
      && typeof finding.line === "number"
      && Number.isInteger(finding.line)
      && finding.line > 0
      && severities.has(finding.severity)
      && categories.has(finding.category)
      && typeof finding.title === "string"
      && typeof finding.description === "string"
      && typeof finding.suggestion === "string");
}

export function isInProgressReview(value: unknown): value is InProgressReview {
  if (!value || typeof value !== "object") return false;
  const review = value as Partial<InProgressReview>;
  return typeof review.headSha === "string"
    && isReplay(review.replay)
    && typeof review.step === "number"
    && Number.isInteger(review.step)
    && review.step >= 0
    && Array.isArray(review.comments)
    && review.comments.every(isPendingComment)
    && typeof review.summary === "string"
    && isReviewEvent(review.event)
    && typeof review.model === "string"
    && typeof review.showFullDiff === "boolean"
    && (review.aiReview === undefined || isAiReview(review.aiReview))
    && (review.scoutModel === undefined || typeof review.scoutModel === "string")
    && (review.reviewerModel === undefined || typeof review.reviewerModel === "string");
}

function isStoredReview(value: unknown): value is StoredReview {
  if (!value || typeof value !== "object") return false;
  const review = value as Partial<StoredReview>;
  return review.version === 1
    && typeof review.updatedAt === "number"
    && isInProgressReview(review);
}

export function loadInProgressReview(storage: Storage, key: string, headSha: string): InProgressReview | null {
  const raw = storage.getItem(key);
  if (!raw) return null;

  try {
    const stored: unknown = JSON.parse(raw);
    if (!isStoredReview(stored) || stored.headSha !== headSha) {
      storage.removeItem(key);
      return null;
    }
    const review: InProgressReview = {
      headSha: stored.headSha,
      replay: stored.replay,
      step: stored.step,
      comments: stored.comments,
      summary: stored.summary,
      event: stored.event,
      model: stored.model,
      showFullDiff: stored.showFullDiff,
    };
    if (stored.aiReview) review.aiReview = stored.aiReview;
    if (stored.scoutModel) review.scoutModel = stored.scoutModel;
    if (stored.reviewerModel) review.reviewerModel = stored.reviewerModel;
    return review;
  } catch {
    storage.removeItem(key);
    return null;
  }
}

export function saveInProgressReview(storage: Storage, key: string, review: InProgressReview): void {
  const stored: StoredReview = { version: 1, updatedAt: Date.now(), ...review };
  storage.setItem(key, JSON.stringify(stored));
}

export function clearInProgressReview(storage: Storage, key: string): void {
  storage.removeItem(key);
}

lib/review-findings.ts.content:
import type { DiffFile, PendingComment, ReviewFinding } from "./types";

const SEVERITY_ORDER = ["critical", "high", "medium", "low"] as const;

export function sortFindings(findings: ReviewFinding[]): ReviewFinding[] {
  return [...findings].sort((left, right) => {
    const severity = SEVERITY_ORDER.indexOf(left.severity) - SEVERITY_ORDER.indexOf(right.severity);
    if (severity !== 0) return severity;
    if (left.file !== right.file) return left.file.localeCompare(right.file);
    return left.line - right.line;
  });
}

export function findingToCommentBody(finding: ReviewFinding): string {
  const sections = [
    `**${finding.severity.toUpperCase()} · ${finding.category}** — ${finding.title}`,
    "",
    finding.description,
  ];
  if (finding.suggestion) sections.push("", "**Suggestion**", "", finding.suggestion);
  sections.push("", "<sub>Generated by Chronosphere AI review.</sub>");
  return sections.join("\n").trim();
}

export function findingAnchor(files: DiffFile[], finding: ReviewFinding): {
  path: string;
  line: number;
  side: "RIGHT";
  changedIndex: number | null;
} | null {
  const file = files.find((candidate) => candidate.path === finding.file);
  const line = file?.hunks.flatMap((hunk) => hunk.lines).find((candidate) => candidate.newLine === finding.line);
  return line ? { path: finding.file, line: finding.line, side: "RIGHT", changedIndex: line.changedIndex } : null;
}

export function findingsAtNewLine(
  findings: ReviewFinding[],
  path: string,
  newLine: number | null,
): ReviewFinding[] {
  if (newLine === null) return [];
  return findings.filter((finding) => finding.file === path && finding.line === newLine);
}

export function isFindingStaged(
  comments: PendingComment[],
  finding: ReviewFinding,
  files: DiffFile[],
): boolean {
  const anchor = findingAnchor(files, finding);
  if (!anchor) return false;
  const body = findingToCommentBody(finding);
  return comments.some((comment) =>
    comment.path === anchor.path
    && comment.line === anchor.line
    && comment.side === anchor.side
    && comment.body === body
  );
}

lib/review-state-store.ts.content:
import { and, eq, lt } from "drizzle-orm";
import { getDb } from "@/db";
import { pullRequestStates } from "@/db/schema";
import type { PullRequestState } from "./review-state";

export interface StoredPullRequestState {
  state: PullRequestState;
  revision: number;
}

export async function loadPullRequestState(
  viewer: string,
  repository: string,
  pullNumber: number,
  headSha: string,
): Promise<StoredPullRequestState | null> {
  const db = await getDb();
  const [row] = await db.select({
    headSha: pullRequestStates.headSha,
    revision: pullRequestStates.revision,
    state: pullRequestStates.state,
  }).from(pullRequestStates).where(and(
    eq(pullRequestStates.viewer, viewer),
    eq(pullRequestStates.repository, repository),
    eq(pullRequestStates.pullNumber, pullNumber),
    eq(pullRequestStates.headSha, headSha),
  )).limit(1);

  if (!row) return null;

  try {
    return { state: JSON.parse(row.state) as PullRequestState, revision: row.revision };
  } catch {
    await deletePullRequestState(viewer, repository, pullNumber, headSha);
    return null;
  }
}

export async function savePullRequestState(
  viewer: string,
  repository: string,
  pullNumber: number,
  state: PullRequestState,
  revision: number,
): Promise<void> {
  const db = await getDb();
  await db.insert(pullRequestStates).values({
    viewer,
    repository,
    pullNumber,
    headSha: state.headSha,
    revision,
    state: JSON.stringify(state),
    updatedAt: new Date(),
  }).onConflictDoUpdate({
    target: [pullRequestStates.viewer, pullRequestStates.repository, pullRequestStates.pullNumber, pullRequestStates.headSha],
    set: {
      headSha: state.headSha,
      revision,
      state: JSON.stringify(state),
      updatedAt: new Date(),
    },
    setWhere: lt(pullRequestStates.revision, revision),
  });
}

export async function deletePullRequestState(
  viewer: string,
  repository: string,
  pullNumber: number,
  headSha: string,
): Promise<void> {
  const db = await getDb();
  await db.delete(pullRequestStates).where(and(
    eq(pullRequestStates.viewer, viewer),
    eq(pullRequestStates.repository, repository),
    eq(pullRequestStates.pullNumber, pullNumber),
    eq(pullRequestStates.headSha, headSha),
  ));
}

lib/review-state.ts.content:
import type { AiReviewResult, PendingComment, ReplayResult } from "./types";
import {
  isAiReview,
  isPendingComment,
  isReplay,
  isReviewEvent,
  type InProgressReview,
  type ReviewEvent,
} from "./review-cache.ts";

export interface ReviewDraft {
  comments: PendingComment[];
  summary: string;
  event: ReviewEvent;
}

export interface PullRequestState {
  headSha: string;
  replay: ReplayResult;
  step: number;
  model: string;
  showFullDiff: boolean;
  aiReview?: AiReviewResult;
  scoutModel?: string;
  reviewerModel?: string;
  review?: ReviewDraft;
}

function isReviewDraft(value: unknown): value is ReviewDraft {
  if (!value || typeof value !== "object") return false;
  const draft = value as Partial<ReviewDraft>;
  return Array.isArray(draft.comments)
    && draft.comments.every(isPendingComment)
    && typeof draft.summary === "string"
    && isReviewEvent(draft.event)
    && (draft.comments.length > 0 || draft.summary.trim().length > 0);
}

export function isPullRequestState(value: unknown): value is PullRequestState {
  if (!value || typeof value !== "object") return false;
  const state = value as Partial<PullRequestState>;
  return typeof state.headSha === "string"
    && isReplay(state.replay)
    && typeof state.step === "number"
    && Number.isInteger(state.step)
    && state.step >= 0
    && typeof state.model === "string"
    && typeof state.showFullDiff === "boolean"
    && (state.aiReview === undefined || isAiReview(state.aiReview))
    && (state.scoutModel === undefined || typeof state.scoutModel === "string")
    && (state.reviewerModel === undefined || typeof state.reviewerModel === "string")
    && (state.review === undefined || isReviewDraft(state.review));
}

export function migrateInProgressReview(review: InProgressReview): PullRequestState {
  const state: PullRequestState = {
    headSha: review.headSha,
    replay: review.replay,
    step: review.step,
    model: review.model,
    showFullDiff: review.showFullDiff,
    aiReview: review.aiReview,
    scoutModel: review.scoutModel,
    reviewerModel: review.reviewerModel,
  };
  if (review.comments.length || review.summary.trim()) {
    state.review = { comments: review.comments, summary: review.summary, event: review.event };
  }
  return state;
}

lib/session.ts.content:
import type { NextRequest } from "next/server";
import type { NextResponse } from "next/server";

export interface SessionData {
  github?: {
    accessToken: string;
    refreshToken?: string;
    expiresAt?: number;
    login: string;
    name: string | null;
    avatarUrl: string;
  };
  openrouter?: {
    apiKey: string;
    userId: string | null;
  };
}

interface OAuthTransaction {
  provider: "github" | "openrouter";
  state?: string;
  verifier: string;
  expiresAt: number;
}

const SESSION_COOKIE = "chronosphere_session";
const TRANSACTION_COOKIE = "chronosphere_oauth";

function secret(): string {
  if (process.env.SESSION_SECRET) return process.env.SESSION_SECRET;
  if (process.env.NODE_ENV === "production") {
    throw new Error("SESSION_SECRET is required in production.");
  }
  return "chronosphere-local-development-secret-change-me";
}

async function key(): Promise<CryptoKey> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(secret()));
  return crypto.subtle.importKey("raw", digest, "AES-GCM", false, ["encrypt", "decrypt"]);
}

function base64url(bytes: Uint8Array): string {
  return Buffer.from(bytes).toString("base64url");
}

async function seal(value: unknown): Promise<string> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const plaintext = new TextEncoder().encode(JSON.stringify(value));
  const ciphertext = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, await key(), plaintext);
  return `${base64url(iv)}.${base64url(new Uint8Array(ciphertext))}`;
}

async function unseal<T>(value: string | undefined): Promise<T | null> {
  if (!value) return null;
  try {
    const [iv, body] = value.split(".");
    if (!iv || !body) return null;
    const plaintext = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv: Buffer.from(iv, "base64url") },
      await key(),
      Buffer.from(body, "base64url")
    );
    return JSON.parse(new TextDecoder().decode(plaintext)) as T;
  } catch {
    return null;
  }
}

function cookieOptions(request: NextRequest, maxAge: number) {
  return {
    httpOnly: true,
    secure: request.nextUrl.protocol === "https:" || process.env.NODE_ENV === "production",
    sameSite: "lax" as const,
    path: "/",
    maxAge,
  };
}

export async function readSession(request: NextRequest): Promise<SessionData> {
  return (await unseal<SessionData>(request.cookies.get(SESSION_COOKIE)?.value)) ?? {};
}

export async function writeSession(
  request: NextRequest,
  response: NextResponse,
  session: SessionData
): Promise<void> {
  response.cookies.set(SESSION_COOKIE, await seal(session), cookieOptions(request, 60 * 60 * 24 * 30));
}

export function clearSession(request: NextRequest, response: NextResponse): void {
  response.cookies.set(SESSION_COOKIE, "", cookieOptions(request, 0));
  response.cookies.set(TRANSACTION_COOKIE, "", cookieOptions(request, 0));
}

export async function writeTransaction(
  request: NextRequest,
  response: NextResponse,
  transaction: OAuthTransaction
): Promise<void> {
  response.cookies.set(TRANSACTION_COOKIE, await seal(transaction), cookieOptions(request, 60 * 10));
}

export async function readTransaction(request: NextRequest): Promise<OAuthTransaction | null> {
  const transaction = await unseal<OAuthTransaction>(request.cookies.get(TRANSACTION_COOKIE)?.value);
  if (!transaction || transaction.expiresAt < Date.now()) return null;
  return transaction;
}

export function clearTransaction(request: NextRequest, response: NextResponse): void {
  response.cookies.set(TRANSACTION_COOKIE, "", cookieOptions(request, 0));
}

export function randomToken(bytes = 32): string {
  return base64url(crypto.getRandomValues(new Uint8Array(bytes)));
}

export async function codeChallenge(verifier: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
  return base64url(new Uint8Array(digest));
}

export function appOrigin(request: NextRequest): string {
  if (process.env.APP_URL) return process.env.APP_URL.replace(/\/$/, "");
  const proto = request.headers.get("x-forwarded-proto")?.split(",")[0] || request.nextUrl.protocol.replace(":", "");
  const host = request.headers.get("x-forwarded-host")?.split(",")[0] || request.headers.get("host");
  return host ? `${proto}://${host}` : request.nextUrl.origin;
}

