tests/diff.test.mjs.content:
import assert from "node:assert/strict";
import test from "node:test";
import { chunkFiles, inRanges, normalizeReplayChunks, parseUnifiedDiff, replayStepMap } from "../lib/diff.ts";

const sample = `diff --git a/src/math.ts b/src/math.ts
index 1111111..2222222 100644
--- a/src/math.ts
+++ b/src/math.ts
@@ -1,3 +1,4 @@
 export function total(values: number[]) {
-  return values.length;
+  const valid = values.filter(Number.isFinite);
+  return valid.reduce((sum, value) => sum + value, 0);
 }
`;

test("parses and numbers changed lines in a unified diff", () => {
  const files = parseUnifiedDiff(sample);
  assert.equal(files.length, 1);
  assert.equal(files[0].path, "src/math.ts");
  assert.deepEqual(
    files[0].hunks[0].lines.filter((line) => line.changedIndex).map((line) => [line.type, line.changedIndex]),
    [["delete", 1], ["add", 2], ["add", 3]],
  );
});

test("normalizes incomplete model output so every changed line is replayed", () => {
  const files = parseUnifiedDiff(sample);
  const chunks = normalizeReplayChunks(
    [{ start: 2, end: 3, title: "Use valid values", description: "Adds the implementation." }],
    files,
  );
  const map = replayStepMap(chunks);
  assert.equal(map.size, 3);
  assert.ok([...map.keys()].every((index) => index >= 1 && index <= 3));
});

test("maps changed lines to their reconstructed step rather than diff order", () => {
  const files = parseUnifiedDiff(sample);
  const chunks = normalizeReplayChunks(
    [
      { start: 2, end: 3, title: "Add the replacement", description: "Adds the new implementation." },
      { start: 1, end: 1, title: "Remove the old return", description: "Removes the old implementation." },
    ],
    files,
  );
  const map = replayStepMap(chunks);

  assert.equal(map.get(2), 0);
  assert.equal(map.get(3), 0);
  assert.equal(map.get(1), 1);
});

test("preserves explicit model impact markings and defaults other steps to false", () => {
  const files = parseUnifiedDiff(sample);
  const chunks = normalizeReplayChunks(
    [
      { start: 2, end: 3, title: "Add the core calculation", description: "Changes the result.", impactful: true },
      { start: 1, end: 1, title: "Remove the old return", description: "Removes the old implementation." },
    ],
    files,
  );

  assert.equal(chunks[0].impactful, true);
  assert.equal(chunks[1].impactful, false);
});

const twoFiles = `diff --git a/src/shape.ts b/src/shape.ts
new file mode 100644
--- /dev/null
+++ b/src/shape.ts
@@ -0,0 +1,3 @@
+export interface Shape {
+  area(): number;
+}
diff --git a/src/circle.ts b/src/circle.ts
new file mode 100644
--- /dev/null
+++ b/src/circle.ts
@@ -0,0 +1,4 @@
+import type { Shape } from "./shape";
+export class Circle implements Shape {
+  area() { return 1; }
+}
`;

test("keeps ranges from several files together in one step", () => {
  const files = parseUnifiedDiff(twoFiles);
  const chunks = normalizeReplayChunks(
    [{ ranges: [{ start: 1, end: 3 }, { start: 5, end: 7 }], title: "Shape and Circle", description: "Defines the interface and its implementation." }],
    files,
  );

  assert.equal(chunks.length, 2);
  assert.deepEqual(chunks[0].ranges, [
    { file: "src/shape.ts", start: 1, end: 3 },
    { file: "src/circle.ts", start: 5, end: 7 },
  ]);
  assert.deepEqual(chunkFiles(chunks[0]), ["src/shape.ts", "src/circle.ts"]);
  assert.equal(chunks[1].title, "Remaining changes");
  assert.deepEqual(chunks[1].ranges, [{ file: "src/circle.ts", start: 4, end: 4 }]);
  assert.equal(replayStepMap(chunks).get(4), 1);
  assert.equal(replayStepMap(chunks).get(6), 0);
});

test("splits a range that crosses a file boundary into one range per file", () => {
  const files = parseUnifiedDiff(twoFiles);
  const chunks = normalizeReplayChunks([{ start: 2, end: 5, title: "Straddle", description: "" }], files);

  assert.deepEqual(chunks[0].ranges, [
    { file: "src/shape.ts", start: 2, end: 3 },
    { file: "src/circle.ts", start: 4, end: 5 },
  ]);
});

test("drops overlapping lines and steps with nothing left to claim", () => {
  const files = parseUnifiedDiff(twoFiles);
  const chunks = normalizeReplayChunks(
    [
      { ranges: [{ start: 1, end: 7 }], title: "Everything", description: "" },
      { ranges: [{ start: 2, end: 3 }], title: "Duplicate", description: "" },
      { ranges: [], title: "Empty", description: "" },
    ],
    files,
  );

  assert.deepEqual(chunks.map((chunk) => chunk.title), ["Everything"]);
  assert.equal(replayStepMap(chunks).size, 7);
});

test("inRanges only matches numbered lines inside a range", () => {
  const ranges = [{ file: "a.ts", start: 2, end: 3 }, { file: "b.ts", start: 9, end: 9 }];
  assert.equal(inRanges(ranges, 2), true);
  assert.equal(inRanges(ranges, 9), true);
  assert.equal(inRanges(ranges, 4), false);
  assert.equal(inRanges(ranges, null), false);
});

tests/pull-sizes.test.mjs.content:
import assert from "node:assert/strict";
import test from "node:test";
import { PULL_SIZES_QUERY, applyPullSizes, pullSizeMap } from "../lib/pull-sizes.ts";

const summary = {
  number: 7,
  title: "Tighten the parser",
  author: { login: "pete", avatarUrl: "https://example.test/pete.png" },
  assignees: [],
  requestedReviewers: [],
  draft: false,
  createdAt: "2026-08-01T00:00:00Z",
  updatedAt: "2026-08-02T00:00:00Z",
  head: "feature",
  base: "main",
  additions: 0,
  deletions: 0,
  changedFiles: 0,
};

const summaries = [summary, { ...summary, number: 9, title: "Add a cache" }];

function payload(nodes) {
  return { repository: { pullRequests: { nodes } } };
}

test("joins GraphQL sizes onto the REST summaries by pull number", () => {
  const sizes = pullSizeMap(payload([
    { number: 9, additions: 12, deletions: 3, changedFiles: 2 },
    { number: 7, additions: 140, deletions: 26, changedFiles: 9 },
  ]));

  const joined = applyPullSizes(summaries, sizes);

  assert.deepEqual(joined[0], { ...summary, additions: 140, deletions: 26, changedFiles: 9 });
  assert.deepEqual(joined[1], { ...summary, number: 9, title: "Add a cache", additions: 12, deletions: 3, changedFiles: 2 });
});

test("leaves pull requests the size query did not cover untouched", () => {
  const joined = applyPullSizes(summaries, pullSizeMap(payload([{ number: 7, additions: 4, deletions: 1, changedFiles: 1 }])));

  assert.equal(joined[0].additions, 4);
  assert.deepEqual(joined[1], { ...summary, number: 9, title: "Add a cache" });
});

test("degrades to the REST summaries when the size payload is unusable", () => {
  for (const unusable of [null, undefined, {}, { repository: null }, payload(null), payload("nope")]) {
    assert.equal(pullSizeMap(unusable).size, 0);
    assert.deepEqual(applyPullSizes(summaries, pullSizeMap(unusable)), summaries);
  }
});

test("skips malformed size nodes rather than emitting junk counts", () => {
  const sizes = pullSizeMap(payload([
    null,
    "nope",
    { number: 7 },
    { number: 7.5, additions: 1, deletions: 1, changedFiles: 1 },
    { number: 11, additions: -4, deletions: 1, changedFiles: 1 },
    { number: 12, additions: "many", deletions: 1, changedFiles: 1 },
    { number: 13, additions: 5, deletions: 2, changedFiles: 1 },
  ]));

  assert.deepEqual([...sizes.keys()], [13]);
  assert.deepEqual(sizes.get(13), { additions: 5, deletions: 2, changedFiles: 1 });
});

test("asks for open pull requests in the order the REST list uses", () => {
  assert.match(PULL_SIZES_QUERY, /states: OPEN/);
  assert.match(PULL_SIZES_QUERY, /orderBy: \{ field: UPDATED_AT, direction: DESC \}/);
  assert.match(PULL_SIZES_QUERY, /number additions deletions changedFiles/);
});

test("reads the shape a successful GraphQL response returns", () => {
  const data = { repository: { pullRequests: { nodes: [{ number: 7, additions: 1, deletions: 2, changedFiles: 3 }] } } };

  assert.deepEqual(pullSizeMap(data).get(7), { additions: 1, deletions: 2, changedFiles: 3 });
});

tests/recording.test.mjs.content:
import assert from "node:assert/strict";
import test from "node:test";
import { mkdtemp, readFile, writeFile, rm, symlink } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { execFileSync, spawnSync } from "node:child_process";
import { contentHash, parseRecording, recordingStateAt } from "../lib/recording.ts";

const recorder = resolve("scripts/record.mjs");
async function fixture(t) {
  const repo = await mkdtemp(join(tmpdir(), "chronosphere-test-"));
  t.after(() => rm(repo, { recursive: true, force: true }));
  execFileSync("git", ["init", "--quiet", repo]);
  await writeFile(join(repo, ".gitignore"), ".chronosphere/\nignored.txt\n");
  const session = join(repo, ".chronosphere", "test.jsonl");
  function run(...args) {
    const result = spawnSync(process.execPath, ["--experimental-strip-types", recorder, ...args], { cwd: repo, encoding: "utf8" });
    if (result.error) throw result.error;
    return result;
  }
  function okay(...args) {
    const result = run(...args);
    assert.equal(result.status, 0, `${result.stdout}\n${result.stderr}`);
    return result;
  }
  function start(...args) { return okay("start", "--out", session, "--title", "Test session", ...args); }
  function checkpoint(title = "Edit") { return okay("checkpoint", "--session", session, "--title", title, "--reason", "Exercise a recorded change."); }
  const read = async () => parseRecording(await readFile(session, "utf8"));
  return { repo, session, run, okay, start, checkpoint, read };
}

test("recordings preserve dirty baselines, successive edits, additions, deletions, and reversals", async (t) => {
  const f = await fixture(t);
  await writeFile(join(f.repo, "math.js"), "original\n");
  execFileSync("git", ["-C", f.repo, "add", "math.js"]);
  await writeFile(join(f.repo, "math.js"), "dirty baseline\n");
  f.start();
  await writeFile(join(f.repo, "math.js"), "first attempt\n");
  await writeFile(join(f.repo, "temporary.js"), "trial\n");
  f.checkpoint("First attempt");
  await writeFile(join(f.repo, "math.js"), "dirty baseline\n");
  await rm(join(f.repo, "temporary.js"));
  f.checkpoint("Reverse attempt");
  f.okay("finish", "--session", f.session, "--title", "Done", "--reason", "Reverted the trial.");
  const log = await f.read();
  assert.equal(recordingStateAt(log, 0).get("math.js").content, "dirty baseline\n");
  assert.equal(recordingStateAt(log, 1).get("math.js").content, "first attempt\n");
  assert.equal(recordingStateAt(log, 1).get("temporary.js").content, "trial\n");
  assert.equal(recordingStateAt(log, 2).get("math.js").content, "dirty baseline\n");
  assert.equal(recordingStateAt(log, 2).has("temporary.js"), false);
  assert.deepEqual(log.events.map((event) => event.sequence), [1, 2, 3]);
  const closed = f.run("checkpoint", "--session", f.session, "--title", "Late", "--reason", "Too late");
  assert.equal(closed.status, 1);
  assert.match(closed.stderr, /finished/);
});

test("command failures retain output, status, and command-created files, without attributing pending edits", async (t) => {
  const f = await fixture(t);
  f.start();
  await writeFile(join(f.repo, "pending.txt"), "pending");
  const args = ["run", "--session", f.session, "--title", "Failing test", "--reason", "Check the first attempt", "--", process.execPath, "-e", "require('fs').writeFileSync('result.txt', 'failed'); console.log('failure evidence'); process.exit(7)"];
  const blocked = f.run(...args);
  assert.equal(blocked.status, 1);
  assert.match(blocked.stderr, /unrecorded edits/);
  f.checkpoint();
  const failed = f.run(...args);
  assert.equal(failed.status, 7);
  const log = await f.read();
  assert.equal(log.events[1].command.exitCode, 7);
  assert.match(log.events[1].command.output, /failure evidence/);
  assert.deepEqual(log.events[1].changes.map((change) => change.path), ["result.txt"]);
  assert.equal(recordingStateAt(log, 2).get("result.txt").content, "failed");
});

test("scope, ignored files, symlinks, binary data and sensitive names are respected", async (t) => {
  const f = await fixture(t);
  await writeFile(join(f.repo, "safe.txt"), "safe\n");
  await writeFile(join(f.repo, "ignored.txt"), "ignored");
  await writeFile(join(f.repo, ".env"), "SECRET=secret");
  await writeFile(join(f.repo, "binary.bin"), Buffer.from([0, 1, 2]));
  await writeFile(join(f.repo, "large.txt"), "x".repeat(256 * 1024 + 1));
  await symlink(join(f.repo, "safe.txt"), join(f.repo, "linked.txt"));
  f.start();
  let log = await f.read();
  assert.deepEqual(Object.keys(log.session.baseline).sort(), [".gitignore", "safe.txt"]);
  assert.deepEqual(log.session.omitted.map((item) => item.path), [".env", "binary.bin", "large.txt", "linked.txt"]);
  await writeFile(join(f.repo, "safe.txt"), Buffer.from([0, 0]));
  f.checkpoint();
  log = await f.read();
  assert.equal(log.events[0].changes.length, 0);
  assert.equal(log.events[0].omitted.some((item) => item.path === "safe.txt"), true);
  assert.equal(recordingStateAt(log, 1).get("safe.txt").content, "safe\n");
});

test("literal scope supports future files, unicode paths, empty content and renames", async (t) => {
  const f = await fixture(t);
  f.start("--include", "café file.txt", "--include", "renamed.txt");
  await writeFile(join(f.repo, "café file.txt"), "");
  await writeFile(join(f.repo, "outside.txt"), "not in scope");
  f.checkpoint();
  await rm(join(f.repo, "café file.txt"));
  await writeFile(join(f.repo, "renamed.txt"), "");
  f.checkpoint();
  const log = await f.read();
  assert.equal(recordingStateAt(log, 1).get("café file.txt").content, "");
  assert.deepEqual([...recordingStateAt(log, 2).keys()], ["renamed.txt"]);
});

test("imports reject tampering, missing events, broken patch preconditions and incomplete JSON", async (t) => {
  const f = await fixture(t);
  await writeFile(join(f.repo, "file.txt"), "one");
  f.start();
  await writeFile(join(f.repo, "file.txt"), "two"); f.checkpoint();
  await writeFile(join(f.repo, "file.txt"), "three"); f.checkpoint();
  const lines = (await readFile(f.session, "utf8")).trim().split("\n").map(JSON.parse);
  const stringify = (records) => records.map((value) => JSON.stringify(value)).join("\n");
  const tampered = structuredClone(lines);
  tampered[1].changes[0].after.content = "tampered";
  await assert.rejects(parseRecording(stringify(tampered)), /hash/);
  await assert.rejects(parseRecording(stringify([lines[0], lines[2]])), /missing, reordered/);
  const broken = structuredClone(lines);
  broken[2].changes[0].before = { content: "different", sha256: await contentHash("different") };
  await assert.rejects(parseRecording(stringify(broken)), /prior state/);
  await assert.rejects(parseRecording(`${stringify(lines)}\n{"type":`), /incomplete/);
  const path = structuredClone(lines);
  path[1].changes[0].path = "../outside";
  await assert.rejects(parseRecording(stringify(path)), /file path/);
});

test("exclusive locks prevent interleaved appends and existing sessions are never overwritten", async (t) => {
  const f = await fixture(t);
  f.start();
  const source = await readFile(f.session, "utf8");
  assert.equal(f.run("start", "--out", f.session, "--title", "Duplicate").status, 1);
  await writeFile(`${f.session}.lock`, "");
  const locked = f.run("checkpoint", "--session", f.session, "--title", "Concurrent", "--reason", "Test lock");
  assert.equal(locked.status, 1);
  assert.match(locked.stderr, /locked/);
  assert.equal(await readFile(f.session, "utf8"), source);
});

test("commands that cannot start still produce a recorded failure", async (t) => {
  const f = await fixture(t);
  f.start();
  const result = f.run("run", "--session", f.session, "--title", "Unavailable command", "--reason", "Check failure capture", "--", "chronosphere-nonexistent-command-123");
  assert.equal(result.status, 1);
  const log = await f.read();
  assert.equal(log.events[0].command.exitCode, null);
  assert.match(log.events[0].command.output, /Could not start command/);
});

test("a previously captured file that becomes ignored is omitted without reading new content", async (t) => {
  const f = await fixture(t);
  await writeFile(join(f.repo, "local.txt"), "public version");
  f.start();
  await writeFile(join(f.repo, ".gitignore"), ".chronosphere/\nlocal.txt\n");
  await writeFile(join(f.repo, "local.txt"), "private version");
  f.checkpoint();
  const log = await f.read();
  assert.equal(recordingStateAt(log, 1).get("local.txt").content, "public version");
  assert.deepEqual(log.events[0].omitted, [{ path: "local.txt", reason: "Now ignored by Git" }]);
  assert.equal((await readFile(f.session, "utf8")).includes("private version"), false);
});

tests/replay-stream.test.mjs.content:
import assert from "node:assert/strict";
import test from "node:test";
import { describeOpenRouterError, lineBuffer, openRouterError, OpenRouterError, openRouterFrame, parseReplayEvent, readOpenRouterContent, readReplayEvents } from "../lib/replay-stream.ts";

function streamOf(chunks) {
  const encoder = new TextEncoder();
  return new ReadableStream({
    start(controller) {
      for (const chunk of chunks) controller.enqueue(encoder.encode(chunk));
      controller.close();
    },
  });
}

async function collect(iterable) {
  const items = [];
  for await (const item of iterable) items.push(item);
  return items;
}

test("releases only complete lines and keeps the trailing partial line", () => {
  const lines = lineBuffer();
  assert.deepEqual(lines.push('{"a":1}\n{"b'), ['{"a":1}']);
  assert.deepEqual(lines.push('":2}\n'), ['{"b":2}']);
  assert.deepEqual(lines.push("tail"), []);
  assert.deepEqual(lines.flush(), ["tail"]);
  assert.deepEqual(lines.flush(), []);
});

test("ignores OpenRouter keep-alives, the done sentinel, and contentless frames", () => {
  assert.equal(openRouterFrame(": OPENROUTER PROCESSING"), null);
  assert.equal(openRouterFrame(""), null);
  assert.equal(openRouterFrame("data: [DONE]"), null);
  assert.equal(openRouterFrame('data: {"choices":[{"delta":{}}]}'), null);
  assert.equal(openRouterFrame("data: not json"), null);
  assert.deepEqual(openRouterFrame('data: {"choices":[{"delta":{"content":"hi"}}]}'), { content: "hi" });
});

test("accumulates model content across SSE frames split mid-line", async () => {
  const deltas = await collect(readOpenRouterContent(streamOf([
    ": OPENROUTER PROCESSING\n\n",
    'data: {"choices":[{"delta":{"content":"{\\"chu"}}]}\n\ndata: {"choices":[{"del',
    'ta":{"content":"nks\\":[]}"}}]}\n\n',
    "data: [DONE]\n",
  ])));

  assert.deepEqual(deltas, ['{"chu', 'nks":[]}']);
  assert.equal(deltas.join(""), '{"chunks":[]}');
});

test("surfaces an OpenRouter error frame as a thrown build failure", async () => {
  await assert.rejects(
    collect(readOpenRouterContent(streamOf([
      'data: {"choices":[{"delta":{"content":"{"}}]}\n',
      'data: {"error":{"message":"openai/nope is not a valid model ID"}}\n',
    ]))),
    { message: "openai/nope is not a valid model ID" },
  );
});

test("keeps OpenRouter's provider, code, and raw upstream error on a mid-stream failure", async () => {
  const payload = {
    id: "gen-1", provider: "Azure",
    error: { code: 500, message: "Provider returned error", metadata: { raw: '{"error":"upstream exploded"}', provider_name: "Azure" } },
    choices: [{ index: 0, delta: { content: "" }, finish_reason: "error" }],
  };
  const frame = `data: ${JSON.stringify(payload)}\n`;
  await assert.rejects(collect(readOpenRouterContent(streamOf([frame]))), (error) => {
    assert.ok(error instanceof OpenRouterError);
    assert.equal(error.message, 'Provider returned error (Azure, code 500): {"error":"upstream exploded"}');
    assert.deepEqual(error.details(), {
      message: error.message, status: undefined, code: 500, provider: "Azure", raw: '{"error":"upstream exploded"}', generationId: undefined,
    });
    return true;
  });
});

test("names the failure even when OpenRouter's error frame carries no message", () => {
  const frame = openRouterFrame('data: {"provider":"Wafer","error":{"code":"server_error"}}');
  assert.ok("error" in frame);
  assert.equal(frame.error.message, "OpenRouter reported an error mid-stream (Wafer, code server_error)");
  assert.equal(openRouterFrame('data: {"error":"plain string"}').error.message, "plain string");
  assert.equal(openRouterError({}), null);
  assert.equal(openRouterError(null), null);
});

test("describes a non-2xx response from its status when the body is not JSON", () => {
  assert.equal(describeOpenRouterError(undefined, { status: 502 }), "OpenRouter returned 502.");
  assert.equal(describeOpenRouterError(undefined, { status: 500, raw: "<html>bad gateway</html>" }), "OpenRouter returned 500: <html>bad gateway</html>");
  assert.equal(describeOpenRouterError("Rate limited", { status: 429, code: 429, provider: "OpenAI" }), "Rate limited (OpenAI)");
  assert.equal(describeOpenRouterError("x", { raw: "y".repeat(300) }).length, "x: ".length + 200 + 1);
});

test("reads the replay event protocol through to the done event", async () => {
  const replay = { model: "openai/gpt-5-mini", truncated: false, chunks: [{ ranges: [{ file: "lib/replay.ts", start: 1, end: 3 }], title: "Add", description: "One step.", impactful: false }] };
  const events = await collect(readReplayEvents(streamOf([
    '{"type":"progress","chars":512}\n{"type":"progress","cha',
    'rs":2048}\n{"type":"parsing"}\n',
    `${JSON.stringify({ type: "done", replay })}\n`,
  ])));

  assert.deepEqual(events, [
    { type: "progress", chars: 512 },
    { type: "progress", chars: 2048 },
    { type: "parsing" },
    { type: "done", replay },
  ]);
});

test("reads a terminal error event and skips unusable lines", async () => {
  const events = await collect(readReplayEvents(streamOf([
    '{"type":"progress","chars":64}\n',
    "\n",
    "half a line that never parses\n",
    '{"type":"error","error":"OpenRouter returned 401."}',
  ])));

  assert.deepEqual(events, [
    { type: "progress", chars: 64 },
    { type: "error", error: "OpenRouter returned 401." },
  ]);
});

test("keeps a malformed event from masquerading as progress", () => {
  assert.equal(parseReplayEvent('{"type":"progress"}'), null);
  assert.equal(parseReplayEvent('{"type":"done"}'), null);
  assert.equal(parseReplayEvent("   "), null);
  assert.deepEqual(parseReplayEvent('{"type":"error"}'), { type: "error", error: "Could not build the replay." });
});

tests/repo-recency.test.mjs.content:
import assert from "node:assert/strict";
import test from "node:test";
import {
  REPO_RECENCY_KEY,
  loadRepoRecency,
  orderByRecency,
  recordRepoOpened,
} from "../lib/repo-recency.ts";

function memoryStorage() {
  const values = new Map();
  return {
    getItem: (key) => values.get(key) ?? null,
    setItem: (key, value) => values.set(key, value),
    removeItem: (key) => values.delete(key),
    clear: () => values.clear(),
    key: (index) => [...values.keys()][index] ?? null,
    get length() { return values.size; },
  };
}

function sealedStorage() {
  return {
    getItem: () => { throw new Error("Storage is unavailable."); },
    setItem: () => { throw new Error("Storage is unavailable."); },
    removeItem: () => {},
    clear: () => {},
    key: () => null,
    length: 0,
  };
}

const repos = ["acme/alpha", "acme/beta", "acme/gamma"].map((fullName, id) => ({ id, fullName }));

test("orders opened repositories first, most recent first", () => {
  const storage = memoryStorage();
  recordRepoOpened(storage, "acme/gamma", 1000);
  recordRepoOpened(storage, "acme/beta", 2000);

  const ordered = orderByRecency(repos, loadRepoRecency(storage));

  assert.deepEqual(ordered.map((repo) => repo.fullName), ["acme/beta", "acme/gamma", "acme/alpha"]);
});

test("keeps the API order when nothing has been opened", () => {
  assert.deepEqual(orderByRecency(repos, {}), repos);
});

test("caps the map at 50 entries by dropping the oldest", () => {
  const storage = memoryStorage();
  for (let index = 0; index < 60; index += 1) recordRepoOpened(storage, `acme/repo-${index}`, 1000 + index);

  const recency = loadRepoRecency(storage);

  assert.equal(Object.keys(recency).length, 50);
  assert.equal(recency["acme/repo-59"], 1059);
  assert.equal(recency["acme/repo-9"], undefined);
});

test("ignores malformed stored recency", () => {
  const storage = memoryStorage();
  storage.setItem(REPO_RECENCY_KEY, "not json");
  assert.deepEqual(loadRepoRecency(storage), {});

  storage.setItem(REPO_RECENCY_KEY, JSON.stringify({ "acme/alpha": "yesterday", "acme/beta": 5 }));
  assert.deepEqual(loadRepoRecency(storage), { "acme/beta": 5 });
});

test("survives storage that throws or is unreachable", () => {
  const storage = sealedStorage();

  assert.deepEqual(loadRepoRecency(storage), {});
  assert.deepEqual(recordRepoOpened(storage, "acme/alpha", 1000), { "acme/alpha": 1000 });
  assert.deepEqual(loadRepoRecency(null), {});
  assert.deepEqual(recordRepoOpened(null, "acme/alpha", 1000), { "acme/alpha": 1000 });
});

tests/review-cache.test.mjs.content:
import assert from "node:assert/strict";
import test from "node:test";
import {
  clearInProgressReview,
  isInProgressReview,
  isReplay,
  loadInProgressReview,
  reviewCacheKey,
  saveInProgressReview,
  upgradeReplay,
} from "../lib/review-cache.ts";

function memoryStorage() {
  const values = new Map();
  return {
    getItem: (key) => values.get(key) ?? null,
    setItem: (key, value) => values.set(key, value),
    removeItem: (key) => values.delete(key),
    clear: () => values.clear(),
    key: (index) => [...values.keys()][index] ?? null,
    get length() { return values.size; },
  };
}

const review = {
  headSha: "abc123",
  replay: {
    model: "openai/gpt-5-mini",
    chunks: [{ ranges: [{ file: "app.ts", start: 1, end: 2 }], title: "Add app", description: "Adds the app." }],
    truncated: false,
  },
  step: 0,
  comments: [{ id: "comment-1", path: "app.ts", line: 2, side: "RIGHT", body: "Please test this.", step: 0 }],
  summary: "One concern.",
  event: "REQUEST_CHANGES",
  model: "openai/gpt-5-mini",
  showFullDiff: false,
};

test("round-trips an in-progress review in browser storage", () => {
  const storage = memoryStorage();
  const key = reviewCacheKey("Pete", "Acme/Widget", 42);

  saveInProgressReview(storage, key, review);

  assert.deepEqual(loadInProgressReview(storage, key, review.headSha), review);
  clearInProgressReview(storage, key);
  assert.equal(storage.length, 0);
});

test("invalidates a cached review when the pull request head changes", () => {
  const storage = memoryStorage();
  const key = reviewCacheKey("Pete", "Acme/Widget", 42);
  saveInProgressReview(storage, key, review);

  assert.equal(loadInProgressReview(storage, key, "new-head"), null);
  assert.equal(storage.length, 0);
});

test("discards malformed cached reviews", () => {
  const storage = memoryStorage();
  const key = reviewCacheKey("Pete", "Acme/Widget", 42);
  storage.setItem(key, "not json");

  assert.equal(loadInProgressReview(storage, key, review.headSha), null);
  assert.equal(storage.length, 0);
});

test("restores an AI review with the draft it belongs to", () => {
  const storage = memoryStorage();
  const key = reviewCacheKey("Pete", "Acme/Widget", 42);
  const aiReview = {
    scoutModel: "openai/gpt-5-mini",
    reviewerModel: "anthropic/claude-sonnet-4",
    scout: { intent: "Check the parser.", focusAreas: [{ file: "app.ts", reason: "Input boundary", risk: "high" }] },
    summary: "One issue found.",
    findings: [{ file: "app.ts", line: 2, severity: "high", category: "correctness", title: "Unchecked input", description: "The input can be empty.", suggestion: "Validate it." }],
    truncated: false,
  };
  const withAiReview = { ...review, aiReview, scoutModel: aiReview.scoutModel, reviewerModel: aiReview.reviewerModel };

  saveInProgressReview(storage, key, withAiReview);

  assert.deepEqual(loadInProgressReview(storage, key, review.headSha), withAiReview);
});

test("validates durable PR state before it reaches the client", () => {
  assert.equal(isInProgressReview(review), true);
  assert.equal(isInProgressReview({ ...review, step: -1 }), false);
  assert.equal(isInProgressReview({
    ...review,
    comments: [{ ...review.comments[0], line: 0 }],
  }), false);
  assert.equal(isInProgressReview({
    ...review,
    aiReview: {
      scoutModel: "openai/gpt-5-mini",
      reviewerModel: "openai/gpt-5",
      scout: { intent: "Inspect it.", focusAreas: [] },
      summary: "A problem.",
      findings: [{ file: "app.ts", line: 2, severity: "urgent", category: "bug", title: "Bad", description: "Bad.", suggestion: "Fix." }],
      truncated: false,
    },
  }), false);
});

test("accepts replays stored before steps could span files and upgrades them in place", () => {
  const legacy = {
    model: "openai/gpt-5-mini",
    truncated: false,
    chunks: [
      { file: "app.ts", start: 1, end: 2, title: "Add app", description: "Adds the app.", impactful: true },
      { ranges: [{ file: "lib.ts", start: 3, end: 3 }, { file: "app.ts", start: 4, end: 5 }], title: "Wire it", description: "" },
    ],
  };
  assert.equal(isReplay(legacy), true);

  const upgraded = upgradeReplay(legacy);
  assert.deepEqual(upgraded.chunks, [
    { ranges: [{ file: "app.ts", start: 1, end: 2 }], title: "Add app", description: "Adds the app.", impactful: true },
    legacy.chunks[1],
  ]);
  assert.equal(upgradeReplay(upgraded), upgraded);
});

test("rejects replay steps whose ranges are missing or malformed", () => {
  const base = { model: "openai/gpt-5-mini", truncated: false };
  assert.equal(isReplay({ ...base, chunks: [{ ranges: [], title: "Empty", description: "" }] }), false);
  assert.equal(isReplay({ ...base, chunks: [{ ranges: [{ file: "a.ts", start: 3, end: 2 }], title: "Backwards", description: "" }] }), false);
  assert.equal(isReplay({ ...base, chunks: [{ ranges: [{ start: 1, end: 2 }], title: "No file", description: "" }] }), false);
  assert.equal(isReplay({ ...base, chunks: [{ title: "No coverage", description: "" }] }), false);
});

tests/review-state-store.test.mjs.content:
import assert from "node:assert/strict";
import test from "node:test";
import { existsSync, mkdtempSync, rmSync } from "node:fs";
import { registerHooks } from "node:module";
import { tmpdir } from "node:os";
import path from "node:path";

const root = new URL("../", import.meta.url);

// The store reaches the database through the "@/" path alias and extensionless
// module specifiers, both of which the bundler resolves. Node needs the same
// mapping to load those modules under `node --test`.
function resolveSource(specifier, parentURL) {
  const base = specifier.startsWith("@/") ? root : parentURL;
  const target = specifier.startsWith("@/") ? specifier.slice(2) : specifier;
  if (base === undefined || (base === parentURL && !target.startsWith("."))) return null;
  for (const candidate of [`${target}.ts`, `${target}/index.ts`]) {
    const url = new URL(candidate, base);
    if (existsSync(url)) return url.href;
  }
  return null;
}

registerHooks({
  resolve(specifier, context, nextResolve) {
    const source = resolveSource(specifier, context.parentURL);
    return nextResolve(source ?? specifier, context);
  },
});

const directory = mkdtempSync(path.join(tmpdir(), "chronosphere-state-"));
const file = path.join(directory, "nested", "state.sqlite");
process.env.SQLITE_PATH = file;
delete process.env.RAILWAY_VOLUME_MOUNT_PATH;

const { deletePullRequestState, loadPullRequestState, savePullRequestState } =
  await import("../lib/review-state-store.ts");
const { isPullRequestState } = await import("../lib/review-state.ts");

test.after(() => rmSync(directory, { recursive: true, force: true }));

const headSha = "0123456789012345678901234567890123456789";
const viewer = "pete";
const repository = "acme/widget";
const pullNumber = 42;

function stateAt(step) {
  return {
    headSha,
    replay: {
      model: "openai/gpt-5-mini",
      chunks: [{ ranges: [{ file: "app.ts", start: 1, end: 2 }], title: "Add app", description: "Adds the app." }],
      truncated: false,
    },
    step,
    model: "openai/gpt-5-mini",
    showFullDiff: false,
  };
}

test("creates the database file and round-trips PR state", async () => {
  assert.equal(isPullRequestState(stateAt(0)), true);

  await savePullRequestState(viewer, repository, pullNumber, stateAt(0), 1);
  assert.equal(existsSync(file), true);

  const stored = await loadPullRequestState(viewer, repository, pullNumber, headSha);
  assert.deepEqual(stored, { state: stateAt(0), revision: 1 });
});

test("returns null for a pull request that has no saved state", async () => {
  assert.equal(await loadPullRequestState(viewer, repository, 999, headSha), null);
});

test("keeps the newer state when a stale revision is saved", async () => {
  await savePullRequestState(viewer, repository, pullNumber, stateAt(5), 4);
  assert.deepEqual(await loadPullRequestState(viewer, repository, pullNumber, headSha), {
    state: stateAt(5),
    revision: 4,
  });

  await savePullRequestState(viewer, repository, pullNumber, stateAt(1), 2);
  assert.deepEqual(await loadPullRequestState(viewer, repository, pullNumber, headSha), {
    state: stateAt(5),
    revision: 4,
  });

  await savePullRequestState(viewer, repository, pullNumber, stateAt(9), 4);
  assert.deepEqual(await loadPullRequestState(viewer, repository, pullNumber, headSha), {
    state: stateAt(5),
    revision: 4,
  });
});

test("advances to a higher revision", async () => {
  await savePullRequestState(viewer, repository, pullNumber, stateAt(7), 5);
  assert.deepEqual(await loadPullRequestState(viewer, repository, pullNumber, headSha), {
    state: stateAt(7),
    revision: 5,
  });
});

test("scopes state to the viewer, repository, and head SHA", async () => {
  const otherSha = "abcdefabcdefabcdefabcdefabcdefabcdefabcd";
  assert.equal(await loadPullRequestState("someone-else", repository, pullNumber, headSha), null);
  assert.equal(await loadPullRequestState(viewer, "acme/other", pullNumber, headSha), null);
  assert.equal(await loadPullRequestState(viewer, repository, pullNumber, otherSha), null);
});

test("deletes state and leaves nothing to load", async () => {
  await deletePullRequestState(viewer, repository, pullNumber, headSha);
  assert.equal(await loadPullRequestState(viewer, repository, pullNumber, headSha), null);
});

