    const number = parsePullNumber(request.nextUrl.searchParams.get("number"));
    const [pull, settings, diffResponse] = await Promise.all([
      githubJson<GitHubPullDetail>(token, `/repos/${fullName}/pulls/${number}`),
      githubJson<RepoSettings>(token, `/repos/${fullName}`).catch((): RepoSettings => ({})),
      githubFetch(token, `/repos/${fullName}/pulls/${number}`, {
        headers: { Accept: "application/vnd.github.v3.diff" },
      }),
    ]);
    const allowedMergeMethods: PullRequestDetail["allowedMergeMethods"] = [];
    if (settings.allow_merge_commit !== false) allowedMergeMethods.push("merge");
    if (settings.allow_squash_merge !== false) allowedMergeMethods.push("squash");
    if (settings.allow_rebase_merge !== false) allowedMergeMethods.push("rebase");
    const detail: PullRequestDetail = {
      number: pull.number,
      title: pull.title,
      body: pull.body ?? "",
      url: pull.html_url,
      state: pull.state,
      merged: pull.merged,
      mergeable: pull.mergeable,
      mergeableState: pull.mergeable_state,
      baseSha: pull.base.sha,
      headSha: pull.head.sha,
      baseRepo: pull.base.repo?.full_name ?? fullName,
      headRepo: pull.head.repo?.full_name ?? fullName,
      commits: pull.commits,
      author: { login: pull.user.login, avatarUrl: pull.user.avatar_url },
      assignees: pull.assignees.map((person) => ({ login: person.login, avatarUrl: person.avatar_url })),
      requestedReviewers: pull.requested_reviewers.map((person) => ({ login: person.login, avatarUrl: person.avatar_url })),
      draft: pull.draft,
      createdAt: pull.created_at,
      updatedAt: pull.updated_at,
      head: pull.head.ref,
      base: pull.base.ref,
      additions: pull.additions,
      deletions: pull.deletions,
      changedFiles: pull.changed_files,
      allowedMergeMethods,
      diff: withoutRecordingDiff(await diffResponse.text()),
    };
    return Response.json({ pull: detail });
  } catch (error) {
    return jsonError(error);
  }
}

import { NextRequest } from "next/server";
import { GitHubError, githubFetch, githubJson, githubToken, jsonError, parsePullNumber, parseRepo } from "@/lib/github";
import { PR_RECORDING_PATH, readRecordingResponse } from "@/lib/pr-recording";

export async function GET(request: NextRequest) {
  try {
    const token = await githubToken(request);
    const { fullName } = parseRepo(request.nextUrl.searchParams.get("repo"));
    const number = parsePullNumber(request.nextUrl.searchParams.get("number"));
    const headSha = request.nextUrl.searchParams.get("headSha");
    if (!headSha || !/^[a-f0-9]{40}$/i.test(headSha)) throw new Error("A valid PR head SHA is required.");
    const pull = await githubJson<{ head: { sha: string; repo: { full_name: string } | null } }>(token, `/repos/${fullName}/pulls/${number}`);
    if (pull.head.sha !== headSha) return Response.json({ error: "This PR changed. Reopen it before loading its recording." }, { status: 409 });
    if (!pull.head.repo) throw new Error("The PR's source repository is unavailable.");
    try {
      const response = await githubFetch(token, `/repos/${pull.head.repo.full_name}/contents/${PR_RECORDING_PATH}?ref=${headSha}`, { headers: { Accept: "application/vnd.github.raw+json" } });
      return Response.json({ source: await readRecordingResponse(response), path: PR_RECORDING_PATH, headSha }, { headers: { "Cache-Control": "no-store" } });
    } catch (error) {
      if (error instanceof GitHubError && error.status === 404) return Response.json({ source: null, path: PR_RECORDING_PATH, headSha }, { headers: { "Cache-Control": "no-store" } });
      throw error;
    }
  } catch (error) { return jsonError(error); }
}

