      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        body: body.body?.trim() ?? "",
        event: body.event,
        commit_id: body.commitId,
        comments,
      }),
    });
    return Response.json({ review: { id: review.id, url: review.html_url } });
  } catch (error) {
    return jsonError(error);
  }
