.timeline-panel { min-height: 0; border-right: 1px solid var(--border); background: var(--surface-2); display: flex; flex-direction: column; }
.timeline-title, .section-title { display: flex; justify-content: space-between; align-items: center; }
.timeline-title { padding: 16px 16px 12px; border-bottom: 1px solid var(--border); font-size: 10px; font-weight: 600; color: var(--muted); }
.timeline-title em, .section-title em { font-style: normal; border: 1px solid var(--border); background: var(--surface); border-radius: var(--radius-full); padding: 2px 7px; color: var(--muted); font: 600 10px var(--font-mono), monospace; }
.timeline-panel ol { list-style: none; margin: 0; padding: 8px 0; overflow: auto; flex: 1; }
.timeline-panel li { position: relative; }
.timeline-panel li:not(:last-child)::after { content: ""; position: absolute; left: 29px; top: 37px; bottom: -9px; width: 1px; background: var(--border-strong); }
.timeline-panel li.past:not(:last-child)::after { background: var(--green-accent); }
.timeline-panel button { width: 100%; border: 0; background: transparent; display: flex; gap: 10px; padding: 8px 12px 8px 16px; text-align: left; cursor: pointer; }
.timeline-panel button:hover { background: var(--surface-3); }
.timeline-panel li.active button { background: var(--accent-soft); }
.step-marker { width: 26px; height: 26px; border: 1px solid var(--border-strong); background: var(--surface); border-radius: 50%; display: grid; place-items: center; flex: none; font: 600 10px var(--font-mono), monospace; position: relative; z-index: 1; }
.timeline-panel li.active .step-marker { background: var(--accent); color: var(--surface); border-color: var(--accent); box-shadow: 0 0 0 4px var(--accent-soft); }
.timeline-panel li.past .step-marker { background: var(--green-accent); border-color: var(--green-accent); color: #ffffff; }
.timeline-panel button > span:last-child { min-width: 0; display: flex; flex-direction: column; gap: 3px; padding-top: 4px; }
.timeline-panel button strong { font-size: 12px; line-height: 1.35; font-weight: 550; color: var(--muted); }
.timeline-panel li.active button strong { color: var(--ink); }
.timeline-panel button code { font-size: 10px; color: var(--faint); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.timeline-model { border-top: 1px solid var(--border); padding: 12px 16px; display: flex; gap: 8px; color: var(--accent); font-size: 11px; }
.timeline-model span { color: var(--faint); line-height: 1.5; min-width: 0; }
.timeline-model strong { color: var(--muted); font: 500 10px var(--font-mono), monospace; word-break: break-all; }
.step-marker .impact-star { position: absolute; top: -5px; right: -5px; padding: 1px; border-radius: 50%; background: var(--surface); color: var(--amber); box-shadow: 0 0 0 1px var(--border-strong); }
.step-title-row { display: flex; align-items: flex-start; gap: 5px; min-width: 0; }
.step-title-row strong { min-width: 0; }
/* The star on the step marker already flags impact; a second in-list badge
   added noise, so it stays narration-only. */
.step-title-row .impact-badge { display: none; }

/* ============================================================================
   Replay: player & narration
   ========================================================================== */

.code-stage { min-width: 0; min-height: 0; display: flex; flex-direction: column; background: var(--bg); }
.player-bar { height: 48px; flex: none; display: flex; align-items: center; gap: 6px; padding: 0 12px; background: var(--surface); border-bottom: 1px solid var(--border); }
.play-button { height: 32px; min-width: 76px; display: flex; align-items: center; justify-content: center; gap: 6px; border: 1px solid var(--solid-bg); border-radius: var(--radius-md); background: var(--solid-bg); color: var(--solid-ink); cursor: pointer; font-size: 12px; font-weight: 600; }
.play-button:hover { background: var(--solid-hover); border-color: var(--solid-hover); }
.player-bar input[type="range"] { flex: 1; accent-color: var(--accent); height: 3px; margin: 0 8px; }
.player-bar > strong { font: 600 12px var(--font-mono), monospace; white-space: nowrap; }
.player-bar > strong span { color: var(--faint); font-weight: 400; }
.rebuild-button { border: 0; border-left: 1px solid var(--border); background: transparent; margin-left: 8px; padding-left: 14px; color: var(--muted); font-size: 12px; cursor: pointer; }
.rebuild-button:hover { color: var(--ink); }
.step-narration { flex: none; padding: 14px 20px 16px; background: var(--surface-2); border-bottom: 1px solid var(--border); }
.step-narration-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.step-meta { display: flex; align-items: center; gap: 8px; min-width: 0; }
.step-meta > span:first-child { color: var(--accent); font-size: 10px; font-weight: 600; white-space: nowrap; }
.step-meta code { color: var(--faint); font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.step-narration h2 { margin: 8px 0 4px; font-size: 16px; letter-spacing: -0.015em; font-weight: 640; }
.step-narration p { margin: 0; color: var(--muted); font-size: 12px; line-height: 1.55; max-width: 760px; }
.step-meta .impact-label { display: inline-flex; align-items: center; gap: 4px; border: 1px solid var(--amber-border); border-radius: var(--radius-full); padding: 2px 7px; background: var(--amber-soft); color: var(--amber); font: 600 10px var(--font-mono), monospace; text-transform: uppercase; letter-spacing: 0.06em; white-space: nowrap; }
.diff-scope-toggle { display: flex; align-items: center; flex: none; padding: 2px; border: 1px solid var(--border); border-radius: var(--radius-md); background: var(--bg); }
.diff-scope-toggle button { height: 24px; border: 0; border-radius: var(--radius-sm); padding: 0 10px; background: transparent; color: var(--muted); font-size: 11px; cursor: pointer; }
.diff-scope-toggle button.active { background: var(--surface); color: var(--ink); box-shadow: var(--shadow-sm); font-weight: 650; }

/* ============================================================================
   Replay: file tabs
   ========================================================================== */

/* A step that spans files shows one tab per file; a single-file step still
   gets its tab so the file name sits in the same place on every step. */
.file-tabs { flex: none; display: flex; align-items: stretch; gap: 2px; padding: 0 12px; background: var(--surface); border-bottom: 1px solid var(--border); overflow-x: auto; scrollbar-width: thin; }
.file-tabs button { flex: none; display: inline-flex; align-items: center; gap: 8px; height: 38px; max-width: 360px; padding: 0 12px; border: 0; border-bottom: 2px solid transparent; margin-bottom: -1px; background: transparent; color: var(--muted); cursor: pointer; min-width: 0; }
.file-tabs button:hover { color: var(--ink); background: var(--surface-2); }
.file-tabs button.active { color: var(--ink); border-bottom-color: var(--accent); }
.file-tabs button code { display: flex; min-width: 0; font-size: 12px; font-weight: 500; white-space: nowrap; }
/* The directory gives way first so the file name stays readable on long paths. */
.file-tabs button code span { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; color: var(--faint); font-weight: 400; }
.file-tabs button.active code span { color: var(--muted); }
.file-tabs button em { flex: none; font: 500 10px var(--font-mono), monospace; font-style: normal; color: var(--faint); white-space: nowrap; }
.file-tabs button .tab-pending { flex: none; display: inline-flex; align-items: center; gap: 3px; border-radius: var(--radius-full); padding: 1px 6px; background: var(--accent-soft); color: var(--accent); font: 600 10px var(--font-mono), monospace; }

/* ============================================================================
   Replay: diff
   ========================================================================== */

.diff-scroll { overflow: auto; flex: 1; padding: 16px; }
.diff-file[hidden] { display: none; }
.diff-file { border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden; background: var(--surface); margin-bottom: 16px; box-shadow: var(--shadow-sm); }
.diff-file > header { height: 36px; background: var(--surface-2); border-bottom: 1px solid var(--border); display: flex; align-items: center; gap: 8px; padding: 0 12px; }
.diff-file > header code { font-size: 12px; font-weight: 500; color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.diff-file > header > span:last-child { margin-left: auto; color: var(--faint); font: 500 10px var(--font-mono), monospace; text-transform: uppercase; letter-spacing: 0.06em; }
.file-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); }
.diff-table { overflow-x: auto; }
.diff-row, .hunk-row, .context-expander { min-width: 620px; display: grid; grid-template-columns: 26px 46px 46px minmax(480px, 1fr); position: relative; border-bottom: 1px solid var(--border); }
.diff-row { min-height: 24px; align-items: stretch; font: 400 12px/1.7 var(--font-mono), monospace; }
.hunk-row { grid-template-columns: 26px 92px minmax(480px, 1fr); background: var(--accent-soft); color: var(--accent); min-height: 28px; align-items: center; font-size: 11px; }
.hunk-row code { padding-left: 12px; }
.context-expander { display: flex; justify-content: center; min-height: 30px; padding: 3px; background: var(--green-soft); }
.context-expander button { min-width: 168px; height: 24px; display: inline-flex; align-items: center; justify-content: center; gap: 5px; border: 1px solid var(--green-border); border-radius: var(--radius-sm); background: var(--surface); color: var(--green); font: 600 11px var(--font-mono), monospace; cursor: pointer; }
.context-expander button:hover { background: var(--green-current); }
.context-expander button:disabled { opacity: 0.45; cursor: wait; }
.line-number { color: var(--faint); text-align: right; padding: 3px 8px 0 0; border-right: 1px solid var(--border); user-select: none; font-size: 12px; }
.diff-row > code { padding: 3px 12px; white-space: pre; color: var(--ink); }
.diff-row > code i { font-style: normal; color: var(--faint); display: inline-block; width: 16px; }
.diff-row.add { background: var(--green-soft); }
.diff-row.add > code i { color: var(--green); font-weight: 600; }
.diff-row.delete { background: var(--red-soft); }
.diff-row.delete > code i { color: var(--red); font-weight: 600; }
.diff-row.current.add { background: var(--green-current); box-shadow: inset 3px 0 var(--green-accent); }
.diff-row.current.delete { background: var(--red-current); box-shadow: inset 3px 0 var(--red-border); }
.add-comment { border: 0; border-right: 1px solid var(--border); background: transparent; color: transparent; cursor: pointer; padding: 0; }
.diff-row:hover .add-comment { color: var(--surface); background: var(--accent); }
.add-comment span { font: 600 14px var(--font-mono), monospace; }
.context-gutter { border-right: 1px solid var(--border); }
.expanded-context { background: var(--surface-2); }
.context-error { padding: 8px 12px; border-top: 1px solid var(--red-border); background: var(--red-soft); color: var(--red); font-size: 12px; }
.diff-row.future-change { background: var(--surface-2); }
.future-change-gutter { border-right: 1px solid var(--border); }
.diff-row.future-change .line-number { color: var(--border-strong); }
.diff-row > code.future-change-note { display: flex; align-items: center; padding-top: 0; padding-bottom: 0; color: var(--faint); }
.future-change-note > button { height: 100%; min-width: 0; max-width: 100%; display: inline-flex; align-items: center; gap: 5px; border: 0; background: transparent; padding: 0; color: var(--accent); font: 600 11px var(--font-mono), monospace; cursor: pointer; }
.future-change-note > button:hover { text-decoration: underline; }
.future-change-note > button span { min-width: 0; overflow: hidden; color: var(--faint); font-weight: 500; text-overflow: ellipsis; }
.future-change-note > span { min-height: 24px; }

/* Syntax highlighting */
.shj-syn-cmnt { color: var(--syntax-comment); font-style: italic; }
.shj-syn-deleted, .shj-syn-err, .shj-syn-kwd { color: var(--syntax-keyword); }
.shj-syn-class { color: var(--syntax-class); }
.shj-syn-type, .shj-syn-oper, .shj-syn-num, .shj-syn-section, .shj-syn-var, .shj-syn-bool { color: var(--syntax-literal); }
.shj-syn-insert, .shj-syn-str { color: var(--syntax-string); }
.shj-syn-func { color: var(--syntax-function); }

/* Inline comment composer & drafts (gutter = 26 + 46 + 46 = 118px) */
.inline-composer { padding: 10px 12px 10px 118px; background: var(--accent-soft); border-bottom: 1px solid var(--accent-border); }
.inline-composer textarea { width: 100%; min-height: 64px; resize: vertical; border: 1px solid var(--accent-border); border-radius: var(--radius-sm); padding: 8px; font-size: 12px; background: var(--surface); color: var(--ink); }
.inline-composer > div { margin-top: 8px; display: flex; justify-content: flex-end; gap: 8px; }
.inline-draft { display: flex; align-items: flex-start; gap: 8px; padding: 8px 12px 8px 118px; border-bottom: 1px solid var(--amber-border); background: var(--amber-soft); font-size: 12px; }
.inline-draft > svg { color: var(--amber); flex: none; margin-top: 2px; }
.inline-draft span { flex: 1; white-space: pre-wrap; }
.inline-draft em { font-style: normal; color: var(--amber); font: 600 10px var(--font-mono), monospace; text-transform: uppercase; letter-spacing: 0.06em; }
.inline-comment-editor { background: var(--amber-soft); border-color: var(--amber-border); }
.inline-comment-editor textarea { border-color: var(--amber-border); }

/* Inline AI findings anchored to diff lines */
.inline-finding { padding: 10px 12px 12px 118px; border-bottom: 1px solid var(--accent-border); background: var(--accent-soft); }
.inline-finding-header { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; color: var(--faint); font: 600 10px var(--font-mono), monospace; text-transform: uppercase; letter-spacing: 0.06em; }
.inline-finding-header > svg { color: var(--accent); flex: none; }
.inline-finding-header > strong { color: var(--ink); font: 650 12px var(--font-inter), Arial, sans-serif; text-transform: none; letter-spacing: normal; }
.inline-finding-header .finding-add, .inline-finding-header .finding-staged { margin-left: auto; }
.inline-finding > p, .inline-finding-suggestion p { margin: 8px 0 0; color: var(--muted); font-size: 12px; line-height: 1.5; white-space: pre-wrap; }
.inline-finding-suggestion { margin-top: 8px; border-left: 2px solid var(--green-border); padding-left: 8px; }
.inline-finding-suggestion > span { color: var(--faint); font: 650 9px var(--font-mono), monospace; text-transform: uppercase; letter-spacing: 0.05em; }
.inline-finding-suggestion p { margin-top: 3px; }

/* ============================================================================
   Review sidebar
   ========================================================================== */

.review-sidebar { min-height: 0; border-left: 1px solid var(--border); background: var(--surface); overflow: auto; }
.review-section { padding: 16px; border-bottom: 1px solid var(--border); }
.section-title { font-size: 12px; font-weight: 650; margin-bottom: 12px; }
.comment-list { max-height: 240px; overflow: auto; }
.sidebar-empty { margin: 4px 0 12px; color: var(--muted); font-size: 12px; line-height: 1.55; }
.sidebar-empty kbd { border: 1px solid var(--border-strong); background: var(--surface-3); border-radius: 4px; padding: 0 4px; font: 600 11px var(--font-mono), monospace; }
.draft-card { border: 1px solid var(--amber-border); background: var(--amber-soft); border-radius: var(--radius-md); padding: 10px; margin-bottom: 8px; }
.draft-card-header { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.draft-card code { color: var(--amber); font-size: 10px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.comment-actions { display: flex; align-items: center; gap: 4px; flex: none; }
.comment-actions button { width: 24px; height: 24px; display: grid; place-items: center; border: 0; border-radius: var(--radius-sm); background: transparent; color: var(--faint); padding: 0; cursor: pointer; }
.comment-actions button:hover { background: var(--accent-soft); color: var(--accent); }
.comment-actions button.delete:hover { background: var(--red-soft); color: var(--red); }
.draft-card p { font-size: 12px; line-height: 1.5; margin: 8px 0; white-space: pre-wrap; }
.draft-card > span { color: var(--faint); font-size: 10px; font-weight: 500; }
.draft-card-editor { display: block; margin: 8px 0; }
.draft-card-editor textarea { width: 100%; min-height: 64px; resize: vertical; border: 1px solid var(--amber-border); border-radius: var(--radius-sm); padding: 8px; background: var(--surface); color: var(--ink); font-size: 12px; }
.draft-card-editor > div { display: flex; justify-content: flex-end; gap: 6px; margin-top: 6px; }

/* AI review */
.ai-review-section .section-title > span { display: flex; align-items: center; gap: 6px; }
.ai-review-section .section-title svg { color: var(--accent); }
.ai-models { display: grid; gap: 8px; }
.ai-models label span { display: block; margin-bottom: 4px; color: var(--faint); font: 600 10px var(--font-mono), monospace; text-transform: uppercase; letter-spacing: 0.08em; }
.ai-models input { width: 100%; height: 32px; border: 1px solid var(--border-strong); border-radius: var(--radius-sm); padding: 0 8px; background: var(--surface); color: var(--ink); font: 500 12px var(--font-mono), monospace; }
.ai-review-button { width: 100%; min-height: 36px; margin-top: 10px; border: 1px solid var(--accent); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; gap: 6px; background: var(--accent); color: var(--surface); font-size: 12px; font-weight: 650; cursor: pointer; }
.ai-review-button:hover { background: var(--accent-strong); border-color: var(--accent-strong); }
.ai-review-button:disabled { opacity: 0.6; cursor: wait; }
.ai-review-button .spinner { width: 13px; height: 13px; border-color: color-mix(in srgb, var(--surface) 40%, transparent); border-top-color: var(--surface); }
.ai-review-error { display: flex; align-items: flex-start; gap: 6px; margin-top: 8px; border: 1px solid var(--red-border); border-radius: var(--radius-sm); padding: 8px; background: var(--red-soft); color: var(--red); font-size: 12px; line-height: 1.45; }
.ai-review-error svg { flex: none; color: currentColor; }
.ai-review-meta { display: flex; flex-direction: column; gap: 3px; color: var(--faint); font-size: 10px; }
.ai-review-meta code { color: var(--muted); }
.ai-review-summary { margin: 10px 0; color: var(--ink); font-size: 12px; line-height: 1.55; white-space: pre-wrap; }
.ai-review-warning { border: 1px solid var(--amber-border); border-radius: var(--radius-sm); padding: 8px; background: var(--amber-soft); color: var(--amber); font-size: 11px; line-height: 1.45; }
.scout-details { margin: 10px 0 12px; border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 8px 10px; }
.scout-details summary { color: var(--muted); font: 600 11px var(--font-mono), monospace; cursor: pointer; }
.scout-details > p, .focus-area p { margin: 8px 0 0; color: var(--muted); font-size: 11px; line-height: 1.5; }
.focus-area { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 6px; margin-top: 8px; }
.focus-area code { overflow: hidden; text-overflow: ellipsis; color: var(--faint); font-size: 10px; white-space: nowrap; }
.focus-area p { grid-column: 1 / -1; margin-top: 0; }
.risk, .severity { border: 1px solid var(--border-strong); border-radius: var(--radius-full); padding: 1px 6px; font: 650 9px var(--font-mono), monospace; text-transform: uppercase; letter-spacing: 0.05em; }
.risk.high, .severity.critical, .severity.high { border-color: var(--red-border); background: var(--red-soft); color: var(--red); }
.risk.medium, .severity.medium { border-color: var(--amber-border); background: var(--amber-soft); color: var(--amber); }
.risk.low, .severity.low { border-color: var(--border-strong); color: var(--muted); }
.findings-heading { display: flex; align-items: center; justify-content: space-between; border-top: 1px solid var(--border); padding: 10px 0 6px; color: var(--faint); font-size: 10px; font-weight: 650; }
.findings-heading button, .finding-add { border: 1px solid var(--accent-border); border-radius: var(--radius-sm); padding: 4px 8px; background: var(--accent-soft); color: var(--accent); font-size: 11px; font-weight: 650; cursor: pointer; letter-spacing: normal; text-transform: none; font-family: var(--font-inter), Arial, sans-serif; }
.no-findings { display: flex; align-items: center; gap: 6px; color: var(--green); }
.finding-card { border: 1px solid var(--border); border-radius: var(--radius-md); padding: 10px; margin-top: 8px; background: var(--surface-2); }
.finding-labels { display: flex; align-items: center; gap: 6px; color: var(--faint); font-size: 9px; font-weight: 600; }
.finding-jump { width: 100%; border: 0; background: transparent; padding: 8px 0 0; display: flex; flex-direction: column; gap: 3px; text-align: left; cursor: pointer; }
.finding-jump strong { color: var(--ink); font-size: 12px; line-height: 1.4; }
.finding-jump:hover strong { color: var(--accent); }
.finding-jump code { overflow: hidden; color: var(--faint); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.finding-card > p, .finding-suggestion p { margin: 8px 0; color: var(--muted); font-size: 11px; line-height: 1.5; white-space: pre-wrap; }
.finding-suggestion { border-left: 2px solid var(--green-border); padding-left: 8px; }
.finding-suggestion span { color: var(--faint); font: 650 9px var(--font-mono), monospace; text-transform: uppercase; letter-spacing: 0.05em; }
.finding-suggestion p { margin-top: 3px; }
.finding-staged, .finding-unanchored { display: inline-flex; align-items: center; gap: 4px; color: var(--amber); font: 600 10px var(--font-mono), monospace; }
.finding-unanchored { color: var(--faint); }
.ai-rerun { width: 100%; margin-top: 10px; }

/* Submit review */
.review-summary { width: 100%; min-height: 80px; resize: vertical; border: 1px solid var(--border-strong); border-radius: var(--radius-md); padding: 10px; font-size: 12px; background: var(--surface-2); color: var(--ink); }
.review-events { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-top: 8px; }
.review-events button { display: flex; align-items: center; justify-content: center; gap: 4px; height: 32px; border: 1px solid var(--border); border-radius: var(--radius-md); background: var(--surface); color: var(--muted); font-size: 11px; cursor: pointer; }
.review-events button:hover { border-color: var(--border-strong); color: var(--ink); }
.review-events button.active { border-color: var(--accent-border); color: var(--accent); background: var(--accent-soft); font-weight: 600; }

/* Merge */
.section-title em.green { color: var(--green); background: var(--green-soft); border-color: var(--green-border); }
.section-title em.red { color: var(--red); background: var(--red-soft); border-color: var(--red-border); }
.section-title em.purple { color: var(--accent); background: var(--accent-soft); border-color: var(--accent-border); }
.section-title em.amber { color: var(--amber); background: var(--amber-soft); border-color: var(--amber-border); }
.merge-facts { display: flex; flex-direction: column; gap: 8px; }
.merge-facts > div { display: flex; justify-content: space-between; align-items: center; font-size: 12px; }
.merge-facts span { color: var(--muted); }
.merge-facts strong { display: flex; align-items: center; gap: 4px; font-weight: 550; text-transform: capitalize; }
.merge-facts code { font-size: 11px; color: var(--muted); }
.merge-warning { color: var(--red); background: var(--red-soft); border: 1px solid var(--red-border); border-radius: var(--radius-sm); padding: 8px; font-size: 12px; line-height: 1.45; }
.select-wrap { position: relative; display: block; margin-top: 12px; }
.select-wrap select { appearance: none; width: 100%; height: 32px; border: 1px solid var(--border-strong); border-radius: var(--radius-md); background: var(--surface); color: var(--ink); padding: 0 28px 0 10px; font-size: 12px; }
.select-wrap svg { position: absolute; right: 8px; top: 9px; pointer-events: none; color: var(--muted); }
.merge-button { width: 100%; height: 36px; margin-top: 8px; border: 1px solid var(--green-accent); background: var(--green-accent); color: #ffffff; border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; gap: 6px; font-size: 12px; font-weight: 600; cursor: pointer; }
.merge-button:hover { background: var(--green); border-color: var(--green); }
.merge-button.confirm { background: var(--solid-bg); border-color: var(--solid-bg); color: var(--solid-ink); }
.cancel-confirm { width: 100%; margin-top: 6px; }
.sidebar-message { margin: 12px 16px; background: var(--green-soft); color: var(--green); border: 1px solid var(--green-border); border-radius: var(--radius-sm); padding: 8px 10px; font-size: 12px; line-height: 1.45; }
.sidebar-message.error { background: var(--red-soft); color: var(--red); border-color: var(--red-border); }

/* ============================================================================
   Responsive
   ========================================================================== */

@media (max-width: 1050px) {
  .replay-grid { grid-template-columns: 216px minmax(460px, 1fr); }
  .review-sidebar { position: fixed; top: 108px; right: 0; bottom: 0; width: 320px; z-index: 30; box-shadow: var(--shadow-md); }
  .picker-grid { grid-template-columns: 265px 1fr; }
}
@media (max-width: 760px) {
  .app-header { padding: 0 14px; }
  .header-context { display: none; }
  .viewer-pill > span { display: none; }
  .auth-card { padding: 32px 24px 28px; }
  .connection-row { grid-template-columns: 28px 40px 1fr; }
  .connection-row .primary-button, .connected-label { grid-column: 3; justify-self: start; }
  .connection-copy span { display: none; }
  .picker-shell { padding: 24px 14px; }
  .picker-intro { align-items: flex-start; }
  .auth-badges { display: none; }
  .picker-grid { grid-template-columns: 1fr; }
  .repo-panel { border-right: 0; border-bottom: 1px solid var(--border); max-height: 260px; }
  .pr-heading { align-items: flex-start; flex-direction: column; }
  .pr-heading-tools { width: 100%; }
  .filter-bar { overflow-x: auto; }
  .filter-bar button { white-space: nowrap; }
  .pr-header { padding: 0 8px; gap: 8px; }
  .pr-header .back-button { font-size: 0; }
  .pr-stats span { display: none; }
  .replay-grid { display: flex; flex-direction: column; overflow: auto; }
  .timeline-panel { display: none; }
  .code-stage { height: 68vh; height: 68dvh; flex: none; }
  .review-sidebar { display: block; position: static; width: auto; max-height: none; flex: none; box-shadow: none; border-left: 0; border-top: 1px solid var(--border); }
  .inline-composer, .inline-draft, .inline-finding { padding-left: 12px; }
}

/* Local recording viewer: preserve the review workspace palette and typography. */
.recording-app { height: auto; min-height: 100dvh; }
.recording-home { display: inline-flex; align-items: center; gap: 8px; color: var(--ink); text-decoration: none; font-size: 14px; font-weight: 600; }
.recording-app .secondary-button, .recording-app .primary-button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; font-size: 14px; }
.recording-app .secondary-button { padding: 8px 12px; background: var(--surface); color: var(--ink); border: 1px solid var(--border-strong); border-radius: 7px; cursor: pointer; }
.recording-app button:disabled { opacity: .5; cursor: default; }
.recording-badge { display: inline-block; width: fit-content; padding: 5px 9px; border: 1px solid var(--border); background: var(--surface); color: var(--muted); border-radius: 5px; font-size: 13px; white-space: nowrap; }
.recording-empty { max-width: 780px; margin: 9vh auto; padding: 30px; }
.recording-empty h1 { font-size: clamp(28px, 4vw, 42px); letter-spacing: -.04em; line-height: 1.15; margin: 22px 0 16px; }
.recording-empty p { color: var(--muted); font-size: 16px; line-height: 1.6; }
.recording-empty .primary-button { margin: 15px 0; }
.recording-empty .recording-privacy { font-size: 14px; }
.recording-instructions { margin-top: 28px; padding-top: 20px; border-top: 1px solid var(--border); }
.recording-instructions summary, .recording-omissions summary { cursor: pointer; font-weight: 600; }
.recording-instructions pre { overflow: auto; font-size: 13px; padding: 15px; background: var(--surface); border: 1px solid var(--border); }
.recording-error { padding: 14px 24px; color: var(--red); background: var(--red-soft); border-bottom: 1px solid var(--red-border); }
.recording-main { display: flex; flex: 1; min-height: 0; flex-direction: column; }
.recording-heading { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 20px 24px; border-bottom: 1px solid var(--border); }
.recording-heading h1 { margin: 0 0 7px; font-size: 22px; overflow-wrap: anywhere; }
.recording-heading p { margin: 0; font-size: 14px; color: var(--muted); }
.recording-notice { padding: 11px 24px; background: var(--accent-soft); color: var(--ink); font-size: 14px; line-height: 1.5; }
.recording-layout { display: grid; grid-template-columns: 270px minmax(0, 1fr); flex: 1; min-height: 0; }
.recording-timeline { border-right: 1px solid var(--border); background: var(--surface); }
.recording-timeline h2 { margin: 0; padding: 18px; display: flex; justify-content: space-between; font-size: 14px; border-bottom: 1px solid var(--border); }
.recording-timeline h2 span { color: var(--muted); font-weight: 400; }
.recording-timeline ol { list-style: none; padding: 8px 0; margin: 0; max-height: 70vh; overflow: auto; }
.recording-timeline button { display: flex; gap: 12px; width: 100%; padding: 13px 16px; border: 0; text-align: left; color: var(--ink); background: transparent; cursor: pointer; }
.recording-timeline button:hover { background: var(--bg); }
.recording-timeline button[aria-current] { background: var(--accent-soft); }
.recording-timeline button > span { display: grid; place-items: center; width: 27px; height: 27px; flex-shrink: 0; border: 1px solid var(--border-strong); border-radius: 50%; font-size: 12px; }
.recording-timeline button[aria-current] > span { background: var(--accent); color: var(--surface); border-color: var(--accent); }
.recording-timeline button strong { display: block; font-size: 14px; line-height: 1.4; overflow-wrap: anywhere; }
.recording-timeline button small { display: block; color: var(--muted); margin-top: 5px; font-size: 12px; }
.recording-stage { min-width: 0; }
.recording-player { display: flex; align-items: center; gap: 10px; padding: 14px 20px; border-bottom: 1px solid var(--border); background: var(--surface); }
.recording-player input { flex: 1; min-width: 45px; accent-color: var(--accent); }
.recording-player > span { white-space: nowrap; color: var(--muted); font-size: 13px; }
.recording-detail { padding: 24px; }
.recording-detail h2 { margin: 0 0 10px; font-size: 22px; overflow-wrap: anywhere; }
.recording-caption { margin: 0; color: var(--muted); font-size: 13px; }
.recording-reason { font-size: 16px; line-height: 1.6; white-space: pre-wrap; overflow-wrap: anywhere; }
.recording-omissions { margin: 18px 0; padding: 14px; border: 1px solid var(--border-strong); color: var(--muted); font-size: 14px; }
.recording-omissions li { overflow-wrap: anywhere; margin: 6px 0; }
.recording-command { background: var(--surface); border: 1px solid var(--border); border-radius: 7px; margin: 20px 0; padding: 16px; }
.recording-command h3 { margin: 0 0 14px; display: flex; justify-content: space-between; font-size: 14px; gap: 15px; }
.recording-command pre { overflow: auto; max-height: 300px; font-size: 13px; line-height: 1.6; }
.recording-pass { color: var(--green); }.recording-fail { color: var(--red); }
.recording-view-switch { display: flex; flex-wrap: wrap; gap: 8px; margin: 24px 0 18px; }
.recording-view-switch button { background: var(--surface); color: var(--muted); border: 1px solid var(--border); border-radius: 6px; padding: 9px 12px; font-size: 14px; cursor: pointer; }
.recording-view-switch button[aria-pressed="true"] { background: var(--accent-soft); color: var(--ink); border-color: var(--accent); }
.recording-workspace label { display: flex; gap: 12px; align-items: center; margin-bottom: 14px; font-size: 14px; }
.recording-workspace select { flex: 1; min-width: 0; padding: 8px; border: 1px solid var(--border); border-radius: 5px; background: var(--surface); color: var(--ink); }
.recording-change { border: 1px solid var(--border); border-radius: 7px; margin-bottom: 20px; overflow: hidden; }
.recording-change > h3 { display: flex; justify-content: space-between; gap: 15px; background: var(--surface); margin: 0; padding: 12px 15px; font-size: 14px; border-bottom: 1px solid var(--border); }
.recording-change > h3 code { overflow-wrap: anywhere; }
.recording-change > h3 span { color: var(--muted); font-size: 12px; font-weight: 400; }
.recording-file-pair { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.recording-file-pair > :first-child { border-right: 1px solid var(--border); }
.recording-source { min-width: 0; background: var(--surface); }
.recording-source h3 { margin: 0; font-size: 13px; font-weight: 500; padding: 9px 15px; background: var(--bg); color: var(--muted); overflow-wrap: anywhere; }
.recording-source pre { margin: 0; padding: 15px; font-size: 13px; line-height: 1.65; max-height: 560px; overflow: auto; tab-size: 2; }
.recording-absent, .recording-no-changes { padding: 15px; font-size: 14px; color: var(--muted); }
@media (max-width: 800px) {
  .recording-layout { grid-template-columns: minmax(0, 1fr); }
  .recording-timeline { border-right: 0; border-bottom: 1px solid var(--border); }
  .recording-timeline ol { max-height: 180px; }
  .recording-file-pair { grid-template-columns: minmax(0, 1fr); }
  .recording-file-pair > :first-child { border-right: 0; border-bottom: 1px solid var(--border); }
  .recording-detail { padding: 18px 12px; }
  .recording-heading { padding: 18px 12px; align-items: flex-start; flex-direction: column; }
  .recording-notice { padding: 12px; }
  .recording-app .app-header { padding: 0 12px; }
  .recording-app .header-right > .recording-badge { display: none; }
  .recording-player { gap: 6px; padding: 12px; }
}

after.content:
@import "tailwindcss";

.replay-source-bar { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; flex: none; padding: 10px 18px; border-bottom: 1px solid var(--border); background: var(--surface); }
.replay-source-bar > span { min-width: 0; overflow-wrap: anywhere; color: var(--muted); font-size: 13px; }
.replay-source-bar > a { margin-left: auto; color: var(--accent); font-size: 14px; }
.replay-source-bar .secondary-button { display: flex; align-items: center; gap: 7px; padding: 7px 10px; border: 1px solid var(--border-strong); border-radius: var(--radius-sm); background: var(--surface); color: var(--ink); cursor: pointer; font-size: 14px; }
.replay-source-bar button:disabled { opacity: .5; cursor: default; }
.recording-review-notice { flex: none; padding: 10px 18px; margin: 0; background: var(--surface-2); border-bottom: 1px solid var(--border); color: var(--muted); font-size: 14px; line-height: 1.5; overflow-wrap: anywhere; }
.recording-review-evidence { margin: 12px; border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--surface); padding: 12px; font-size: 14px; }
.recording-review-evidence summary { cursor: pointer; font-weight: 600; }
.recording-review-evidence pre { overflow: auto; max-height: 260px; font: 13px/1.6 var(--font-mono), monospace; }
.recording-review-evidence li { overflow-wrap: anywhere; }
.historical-comment-hint { margin: 0 0 8px; color: var(--muted); font-size: 14px; line-height: 1.5; }

/* ============================================================================
   Design tokens

   Type scale ......... 10px mono uppercase micro-labels · 11px meta · 12px
                        secondary/code · 13px body · 14px+ headings
   Spacing ............ 4px grid (4 / 8 / 12 / 16 / 20 / 24 / 32)
   Radii .............. sm 6 · md 8 · lg 12 · xl 16 · full
   Color .............. semantic tokens only; components never use raw hex,
                        so dark mode is a token swap rather than overrides.
   ========================================================================== */

:root {
  /* Neutrals */
  --bg: #f6f6f2;
  --surface: #ffffff;
  --surface-2: #fafaf7;
  --surface-3: #f1f1ec;
  --border: #e4e4de;
  --border-strong: #c9cac3;
  --ink: #16181a;
  --muted: #62696f;
  --faint: #93999e;
  --header-bg: rgba(246, 246, 242, 0.92);

  /* Accent */
  --accent: #5b46f2;
  --accent-strong: #4a38d6;
  --accent-soft: #eceaff;
  --accent-border: #c6befa;

  /* Brand */
  --lime: #c9f65a;
  --lime-dark: #84a927;
  --lime-soft: #eff6dc;

  /* Semantic */
  --green: #17803e;
  --green-accent: #31a556;
  --green-soft: #e5f5e9;
  --green-current: #c8ecd1;
  --green-border: #7cc48d;
  --red: #c4303e;
  --red-soft: #fdeaec;
  --red-current: #f6ccd1;
  --red-border: #dd7b84;
  --amber: #96610d;
  --amber-soft: #fdf4dc;
  --amber-border: #e3cd8d;

  /* Solid high-contrast controls (primary buttons, play, confirm) */
  --solid-bg: #1b1e20;
  --solid-hover: #303436;
  --solid-ink: #ffffff;

  /* Syntax */
  --syntax-comment: #6e7781;
  --syntax-keyword: #cf222e;
  --syntax-class: #953800;
  --syntax-literal: #0550ae;
  --syntax-string: #0a3069;
  --syntax-function: #8250df;

  /* Elevation */
  --shadow-sm: 0 1px 3px rgba(18, 21, 23, 0.05);
  --shadow-md: 0 10px 32px rgba(18, 21, 23, 0.07);
  --shadow-lg: 0 24px 70px rgba(18, 21, 23, 0.1);

  /* Shape */
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 999px;

  color-scheme: light;
}

html[data-theme="dark"] {
  --bg: #0e1011;
  --surface: #16191b;
  --surface-2: #1a1e20;
  --surface-3: #23282b;
  --border: #282d30;
  --border-strong: #3a4145;
  --ink: #edf1ef;
  --muted: #a3abae;
  --faint: #798286;
  --header-bg: rgba(14, 16, 17, 0.92);

  --accent: #a99cff;
  --accent-strong: #bcb1ff;
  --accent-soft: #2d2950;
  --accent-border: #5a5297;

  --lime: #b8e64d;
  --lime-dark: #9fc53e;
  --lime-soft: #27321a;

  --green: #72dc90;
  --green-accent: #42bd67;
  --green-soft: #17331f;
  --green-current: #20512e;
  --green-border: #3f9f5a;
  --red: #ff858e;
  --red-soft: #381b20;
  --red-current: #55242a;
  --red-border: #c85560;
  --amber: #efb04c;
  --amber-soft: #2d2617;
  --amber-border: #5c4d26;

  --solid-bg: #e4e9e7;
  --solid-hover: #ffffff;
  --solid-ink: #16191b;

  --syntax-comment: #8b949e;
  --syntax-keyword: #ff7b72;
  --syntax-class: #ffa657;
  --syntax-literal: #79c0ff;
  --syntax-string: #a5d6ff;
  --syntax-function: #d2a8ff;

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 10px 32px rgba(0, 0, 0, 0.35);
  --shadow-lg: 0 24px 70px rgba(0, 0, 0, 0.45);

  color-scheme: dark;
}

/* ============================================================================
   Base
   ========================================================================== */

* { box-sizing: border-box; }
html, body { min-height: 100%; }
body { margin: 0; background: var(--bg); color: var(--ink); font-family: var(--font-inter), Arial, sans-serif; font-size: 14px; }
button, input, textarea, select { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button, a, input, textarea, select { transition: background-color 0.12s ease, border-color 0.12s ease, color 0.12s ease, box-shadow 0.12s ease; }
button:focus-visible, a:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
code, .line-number { font-family: var(--font-mono), monospace; }

/* Shared micro-label: uppercase mono used for kickers, badges, and statuses */
.kicker, .timeline-title, .step-meta > span:first-child, .findings-heading, .finding-labels, .draft-card > span, .draft-badge, .connection-index { font-family: var(--font-mono), monospace; text-transform: uppercase; letter-spacing: 0.08em; }

.app-frame { height: 100vh; height: 100dvh; display: flex; flex-direction: column; }

/* ============================================================================
   App header
   ========================================================================== */

.app-header { height: 56px; flex: none; display: flex; align-items: center; justify-content: space-between; padding: 0 20px; border-bottom: 1px solid var(--border); background: var(--header-bg); backdrop-filter: blur(14px); position: relative; z-index: 50; }
.brand { display: flex; align-items: center; gap: 10px; font-size: 15px; font-weight: 650; letter-spacing: -0.02em; }
.brand-mark { width: 28px; height: 28px; border: 1.5px solid var(--ink); border-radius: 50%; display: grid; place-items: center; position: relative; color: var(--ink); }
.brand-mark span { position: absolute; inset: 4px; border: 1px solid var(--lime-dark); border-radius: 50%; border-left-color: transparent; transform: rotate(-28deg); }
.header-right, .viewer-pill, .auth-badges, .pr-stats, .pr-identity, .people, .assignment-row, .pr-meta { display: flex; align-items: center; }
.header-right { gap: 16px; }
.header-context { color: var(--muted); font-size: 12px; }
.viewer-pill { gap: 8px; border-left: 1px solid var(--border); padding-left: 16px; font-size: 12px; }
.avatar { border-radius: 50%; object-fit: cover; background: var(--surface-3); flex: none; }
.icon-button { border: 1px solid var(--border-strong); background: var(--surface); color: var(--ink); width: 32px; height: 32px; border-radius: var(--radius-md); display: grid; place-items: center; cursor: pointer; }
.icon-button:hover { background: var(--surface-3); }
.icon-button:disabled { opacity: 0.35; cursor: default; }
.icon-button.quiet { border: 0; background: transparent; width: 26px; height: 26px; color: var(--muted); }
.icon-button.quiet:hover { color: var(--ink); background: var(--surface-3); }
.theme-toggle { flex: none; }
.theme-toggle .sun-icon { display: none; }
html[data-theme="dark"] .theme-toggle .sun-icon { display: block; }
html[data-theme="dark"] .theme-toggle .moon-icon { display: none; }

/* ============================================================================
   Shared primitives
   ========================================================================== */

.eyebrow { display: flex; align-items: center; gap: 7px; color: var(--accent); text-transform: uppercase; letter-spacing: 0.12em; font: 600 11px var(--font-mono), monospace; }
.kicker { font-size: 10px; font-weight: 600; color: var(--faint); }
.primary-button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; border: 1px solid var(--solid-bg); border-radius: var(--radius-md); padding: 10px 16px; color: var(--solid-ink); background: var(--solid-bg); text-decoration: none; font-size: 13px; font-weight: 600; cursor: pointer; }
.primary-button:hover { background: var(--solid-hover); border-color: var(--solid-hover); }
.primary-button:disabled, .primary-button.disabled { opacity: 0.45; cursor: default; }
.primary-button.compact { padding: 7px 12px; font-size: 12px; }
.primary-button.full { width: 100%; margin-top: 12px; }
.text-button { border: 0; background: transparent; color: var(--muted); font-size: 12px; cursor: pointer; }
.text-button:hover { color: var(--ink); }
.error-banner { display: flex; align-items: flex-start; gap: 8px; margin-top: 16px; color: var(--red); background: var(--red-soft); border: 1px solid var(--red-border); border-radius: var(--radius-md); padding: 10px 12px; font-size: 12px; line-height: 1.5; }
.error-banner.wide { margin: 0 0 16px; }
.search-field { height: 34px; display: flex; align-items: center; gap: 8px; border: 1px solid var(--border); border-radius: var(--radius-md); padding: 0 10px; color: var(--faint); background: var(--surface-2); }
.search-field:focus-within { border-color: var(--accent-border); box-shadow: 0 0 0 3px var(--accent-soft); }
.search-field input { width: 100%; border: 0; outline: 0; background: transparent; font-size: 12px; color: var(--ink); }
.spinner { width: 14px; height: 14px; border: 2px solid var(--border-strong); border-top-color: var(--accent); border-radius: 50%; animation: spin 0.7s linear infinite; flex: none; }
.spinner.large { width: 24px; height: 24px; border-width: 3px; }
@keyframes spin { to { transform: rotate(360deg); } }
.empty-state { min-height: 150px; display: flex; align-items: center; justify-content: center; gap: 8px; color: var(--muted); font-size: 12px; padding: 28px; }
.loading-screen { flex: 1; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 10px; color: var(--muted); }
.loading-screen strong { color: var(--ink); }
.muted { color: var(--faint); }

/* ============================================================================
   Connection gate
   ========================================================================== */

.auth-shell { flex: 1; display: grid; place-items: center; position: relative; overflow: hidden; overflow-y: auto; padding: 56px 24px; }
.auth-orbit { width: 730px; height: 730px; border: 1px solid var(--border); border-radius: 50%; position: absolute; pointer-events: none; }
.auth-orbit::before, .auth-orbit::after { content: ""; position: absolute; border: 1px solid var(--border); border-radius: 50%; inset: 85px; }
.auth-orbit::after { inset: 205px; border-color: var(--border-strong); }
.auth-orbit span { position: absolute; width: 8px; height: 8px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 5px var(--accent-soft); }
.auth-orbit span:nth-child(1) { top: 118px; left: 90px; }
.auth-orbit span:nth-child(2) { right: 27px; top: 355px; background: var(--lime-dark); box-shadow: 0 0 0 5px var(--lime-soft); }
.auth-orbit span:nth-child(3) { bottom: 64px; left: 245px; background: var(--ink); box-shadow: 0 0 0 5px var(--surface-3); }
.auth-card { width: min(680px, 100%); position: relative; padding: 48px 52px 40px; background: color-mix(in srgb, var(--surface) 93%, transparent); border: 1px solid var(--border); border-radius: var(--radius-xl); box-shadow: var(--shadow-lg); }
