  const eligible = new Set(git(repo, "ls-files", "-z", "--cached", "--others", "--exclude-standard").split("\0").filter(Boolean));
  const candidates = new Set([...eligible, ...previous.keys()]);
  const files = new Map(), omitted = [];
  let size = 0;
  for (const name of [...candidates].sort()) {
    if (!scope.some((prefix) => prefix === "." || name === prefix || name.startsWith(`${prefix}/`))) continue;
    validScope(name);
    let reason = excluded(name) ? "Excluded name" : !eligible.has(name) ? "Now ignored by Git" : null;
    const target = resolve(repo, name);
    let stat;
    try { stat = await lstat(target); } catch (error) { if (error.code === "ENOENT") continue; throw error; }
    if (!reason && (!stat.isFile() || stat.isSymbolicLink())) reason = "Not a regular file";
    if (!reason && stat.size > RECORDING_MAX_FILE_BYTES) reason = "Larger than 256 KB";
    if (!reason) {
      const actual = await realpath(target);
      if (!actual.startsWith(`${repo}${sep}`) || actual !== target) reason = "Symlink or outside repository";
    }
    let content;
    if (!reason) {
      const bytes = await readFile(target);
      if (bytes.length > RECORDING_MAX_FILE_BYTES) reason = "Larger than 256 KB";
      else if (bytes.includes(0)) reason = "Binary file";
      else { try { content = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes); } catch { reason = "Not UTF-8 text"; } }
    }
    if (reason) {
      omitted.push({ path: name, reason });
      // Preserve last known text rather than inventing a deletion for an unreadable file.
      if (previous.has(name)) files.set(name, previous.get(name));
      continue;
    }
    size += Buffer.byteLength(content);
    if (size > 8 * 1024 * 1024 || files.size >= 5000) throw new Error("Snapshot is too large. Start a new session with a narrower --include scope.");
    files.set(name, { content, sha256: await contentHash(content) });
  }
  return { files, omitted };
}
function changesBetween(before, after) {
  return [...new Set([...before.keys(), ...after.keys()])].sort().flatMap((path) => {
    const oldFile = before.get(path) ?? null, newFile = after.get(path) ?? null;
    return oldFile?.sha256 === newFile?.sha256 ? [] : [{ path, before: oldFile, after: newFile }];
  });
}
async function durableWrite(file, content, flags) {
  const handle = await open(file, flags, 0o600);
  try { await handle.writeFile(content); await handle.sync(); } finally { await handle.close(); }
}
async function execute(argv, cwd) {
  if (!argv?.length) throw new Error("run requires -- COMMAND [ARGS...]");
  let output = "", truncated = false;
  return new Promise((resolveResult, reject) => {
    const child = spawn(argv[0], argv.slice(1), { cwd, stdio: ["ignore", "pipe", "pipe"], shell: false });
    const capture = (chunk, stream) => {
      stream.write(chunk);
      const room = Math.max(0, 32000 - output.length);
      const data = chunk.toString();
      output += data.slice(0, room);
      truncated ||= data.length > room;
    };
    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk) => capture(chunk, process.stdout));
    child.stderr.on("data", (chunk) => capture(chunk, process.stderr));
    child.on("error", (error) => {
      if (error.code === "ENOENT" || error.code === "EACCES") {
        resolveResult({ argv, exitCode: null, signal: null, output: `Could not start command: ${error.message}`, truncated: false });
      } else reject(error);
    });
    child.on("close", (exitCode, signal) => resolveResult({ argv, exitCode, signal, output, truncated }));
  });
}

export async function main(argv) {
  if (!argv.length || argv[0] === "--help") { console.log(HELP); return 0; }
  const { operation, options } = args([...argv]);
  if (!["start", "checkpoint", "run", "finish", "inspect", "export"].includes(operation)) throw new Error(`Unknown operation: ${operation}`);
  if (operation === "start") {
    const repo = await realpath(git(resolve(options.repo ?? "."), "rev-parse", "--show-toplevel"));
    const scope = (options.include.length ? options.include : ["."]).map(validScope);
    const title = text(options.title, "--title"), id = randomUUID();
    const destination = resolve(options.out ?? `${repo}/.chronosphere/recordings/${id}.jsonl`);
    // The log and local locator must not capture themselves, including with --out.
    const outputInRepo = relative(repo, destination);
    if (!outputInRepo.startsWith("..") && !outputInRepo.startsWith(`.chronosphere${sep}`)) throw new Error("Place --out outside the repository or inside .chronosphere/.");
    const { files, omitted } = await snapshot(repo, scope);
    const session = { type: "session", format: "chronosphere.recording", version: 1, id, createdAt: new Date().toISOString(), title, capture: "checkpoints", repository: { name: basename(repo), head: gitOptional(repo, "rev-parse", "HEAD"), branch: gitOptional(repo, "symbolic-ref", "--short", "HEAD") }, scope, baseline: Object.fromEntries(files), omitted };
    const source = `${JSON.stringify(session)}\n`;
    if (Buffer.byteLength(source) > RECORDING_MAX_BYTES) throw new Error("Starting snapshot exceeds 20 MB when encoded. Use a narrower --include scope.");
    await mkdir(dirname(destination), { recursive: true, mode: 0o700 });
    await durableWrite(destination, source, "wx");
    // Local-only locator: absolute paths never enter the portable recording.
    await durableWrite(`${destination}.local.json`, JSON.stringify({ repo, sessionId: id }), "wx");
    console.log(destination);
    console.log(`Captured ${files.size} text files; omitted ${omitted.length}.`);
    return 0;
  }
  const destination = resolve(text(options.session, "--session"));
  if (operation === "export") {
    const source = await readFile(destination, "utf8");
    const recording = await parseRecording(source);
    if (recording.events.at(-1)?.type !== "finish") throw new Error("Finish the session before exporting a recording for a PR.");
    let output;
    if (options.out) output = resolve(options.out);
    else {
      const locator = JSON.parse(await readFile(`${destination}.local.json`, "utf8"));
      if (locator.sessionId !== recording.session.id) throw new Error("Local locator belongs to a different session.");
      output = resolve(locator.repo, ".chronosphere/replay.jsonl");
    }
    if (output === destination || output === `${destination}.local.json`) throw new Error("Export must not overwrite the original session or its local locator.");
    await mkdir(dirname(output), { recursive: true, mode: 0o700 });
    const temporary = `${output}.${randomUUID()}.tmp`;
    try { await durableWrite(temporary, source, "wx"); await rename(temporary, output); }
    finally { await unlink(temporary).catch((error) => { if (error.code !== "ENOENT") throw error; }); }
    console.log(`Exported recording for your PR:\n${output}\nCommit only the exported .jsonl; keep raw sessions and .local.json files local.`);
    return 0;
  }
  if (operation === "inspect") {
    const recording = await parseRecording(await readFile(destination, "utf8"));
    console.log(JSON.stringify({ title: recording.session.title, events: recording.events.length, files: recordingStateAt(recording, recording.events.length).size, finished: recording.events.at(-1)?.type === "finish" }, null, 2));
    return 0;
  }
  const title = text(options.title, "--title"), reason = text(options.reason, "--reason");
  const lock = `${destination}.lock`;
  let handle;
  try { handle = await open(lock, "wx", 0o600); }
  catch (error) { if (error.code === "EEXIST") throw new Error("Session is locked by another recorder. If it crashed, remove the .lock file only after confirming it is no longer running."); throw error; }
  try {
    const source = await readFile(destination, "utf8");
    const recording = await parseRecording(source);
    if (!source.endsWith("\n")) throw new Error("Recording is missing its final newline; refusing to append.");
    if (recording.events.at(-1)?.type === "finish") throw new Error("This recording is finished. Start a new session.");
    if (recording.events.length >= RECORDING_MAX_EVENTS) throw new Error("Recording has reached its event limit.");
    const locator = JSON.parse(await readFile(`${destination}.local.json`, "utf8"));
    if (locator.sessionId !== recording.session.id) throw new Error("Local locator belongs to a different session.");
    const repo = await realpath(locator.repo);
    const previous = recordingStateAt(recording, recording.events.length);
    if (operation === "run") {
      const beforeCommand = await snapshot(repo, recording.session.scope, previous);
      if (changesBetween(previous, beforeCommand.files).length) throw new Error("There are unrecorded edits. Capture a checkpoint before running a command so its changes have the right explanation.");
    }
    const command = operation === "run" ? await execute(options.command, repo) : undefined;
    const current = await snapshot(repo, recording.session.scope, previous);
    const event = { type: operation === "checkpoint" ? "change" : operation === "run" ? "command" : "finish", id: randomUUID(), sequence: recording.events.length + 1, recordedAt: new Date().toISOString(), title, reason, changes: changesBetween(previous, current.files), omitted: current.omitted, ...(command ? { command } : {}) };
    const line = `${JSON.stringify(event)}\n`;
    if (Buffer.byteLength(source) + Buffer.byteLength(line) > RECORDING_MAX_BYTES) throw new Error("Recording would exceed 20 MB. Start a new scoped session.");
    await durableWrite(destination, line, "a");
    console.log(`Recorded #${event.sequence}: ${title} (${event.changes.length} changed files, ${event.omitted.length} omitted).`);
    return command ? command.exitCode ?? 1 : 0;
  } finally { await handle.close(); await unlink(lock); }
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main(process.argv.slice(2)).then((code) => { process.exitCode = code; }).catch((error) => { console.error(error.message); process.exitCode = 1; });
}

import assert from "node:assert/strict";
import test from "node:test";
import { contentHash, parseRecording } from "../lib/recording.ts";
import { historicalReviewNote, recordedChangeDiff, recordedLineAnchor, recordingReplay } from "../lib/recording-review.ts";
import { parseUnifiedDiff } from "../lib/diff.ts";
import { isReplay, loadInProgressReview, saveInProgressReview } from "../lib/review-cache.ts";
import { isPullRequestState } from "../lib/review-state.ts";
import { PR_RECORDING_PATH, readRecordingResponse, withoutRecordingDiff } from "../lib/pr-recording.ts";

const file = async (content) => ({ content, sha256: await contentHash(content) });
const canonicalDiff = `diff --git a/math.js b/math.js
--- a/math.js
+++ b/math.js
@@ -1,3 +1,4 @@
 export function total(values) {
-  return values.length;
+  const count = values.reduce((a, b) => a + b, 0);
+  return count;
 }
`;

test("recorded file replacements render additions, removals and context with their actual line numbers", async () => {
  const change = { path: "math.js", before: await file("first\nold\nlast\n"), after: await file("first\nnew\nextra\nlast\n") };
  const result = recordedChangeDiff(change);
  assert.deepEqual(result.hunks[0].lines.map(({ type, text, oldLine, newLine }) => [type, text, oldLine, newLine]), [
    ["context", "first", 1, 1], ["delete", "old", 2, null], ["add", "new", null, 2], ["add", "extra", null, 3], ["context", "last", 3, 4],
  ]);
  assert.equal(recordedChangeDiff({ ...change, before: null }).status, "added");
  assert.equal(recordedChangeDiff({ ...change, after: null }).status, "deleted");
  assert.equal(recordedChangeDiff({ path: "empty", before: null, after: await file("") }).hunks.length, 0);
});

test("inline comments require a verified PR file version and an actual diff line", async () => {
  const change = { path: "math.js", before: await file("export function total(values) {\n  return values.length;\n}\n"), after: await file("export function total(values) {\n  const count = values.reduce((a, b) => a + b, 0);\n  return count;\n}\n") };
  const canonical = parseUnifiedDiff(canonicalDiff)[0];
  const rows = recordedChangeDiff(change).hunks[0].lines;
  const added = rows.find((row) => row.type === "add");
  const deleted = rows.find((row) => row.type === "delete");
  const hashes = { baseHash: change.before.sha256, headHash: change.after.sha256 };
  assert.deepEqual(recordedLineAnchor(change, added, canonical, hashes), { path: "math.js", line: 2, side: "RIGHT" });
  assert.deepEqual(recordedLineAnchor(change, deleted, canonical, hashes), { path: "math.js", line: 2, side: "LEFT" });
  assert.equal(recordedLineAnchor(change, added, canonical, {}), null);
  assert.equal(recordedLineAnchor(change, added, canonical, { headHash: "different version" }), null);
  assert.equal(recordedLineAnchor(change, { ...added, newLine: 88 }, canonical, hashes), null);
  assert.equal(recordedLineAnchor(change, { ...added, text: "different text" }, canonical, hashes), null);
  assert.equal(recordedLineAnchor(change, added, undefined, hashes), null);
  assert.deepEqual(recordedLineAnchor(change, deleted, { ...canonical, path: "renamed.js", oldPath: "math.js" }, hashes), { path: "renamed.js", line: 2, side: "LEFT" });
});

test("historical notes preserve the recording location without pretending to have a GitHub anchor", () => {
  const note = historicalReviewNote({ id: "event-1", sequence: 4, title: "Try a cache" }, "cache.js", 8, "RIGHT", "Please explain this choice.");
  assert.match(note, /Recorded step 4: Try a cache/);
  assert.match(note, /cache.js:8 \(after; historical version, event event-1\)/);
  assert.match(note, /Please explain this choice/);
});

test("recorded steps with no final diff ranges persist with review comments, without source snapshots", async () => {
  const before = await file("private source body\n");
  const session = { type: "session", format: "chronosphere.recording", version: 1, capture: "checkpoints", id: "session", title: "Record", createdAt: "2026-09-15T00:00:00Z", repository: { name: "repo", head: null, branch: "main" }, scope: ["."], baseline: { "app.js": before }, omitted: [] };
  const events = [{ type: "finish", id: "finish", sequence: 1, recordedAt: "2026-09-15T00:01:00Z", title: "Done", reason: "Tests pass", changes: [], omitted: [] }];
  const recording = await parseRecording([session, ...events].map(JSON.stringify).join("\n"));
  const replay = recordingReplay(recording, "example.jsonl");
  assert.equal(isReplay(replay), true);
  assert.equal(replay.chunks.length, 2);
  assert.equal(JSON.stringify(replay).includes("private source body"), false);
  assert.equal(isReplay({ ...replay, source: undefined }), false);
  const state = { headSha: "a".repeat(40), replay, step: 1, model: "test", showFullDiff: false, review: { comments: [{ id: "c", path: "app.js", line: 2, side: "RIGHT", body: "Check this", step: 1 }], summary: "Historical note", event: "COMMENT" } };
  assert.equal(isPullRequestState(state), true);
  const storage = new Map();
  const adapter = { getItem: (key) => storage.get(key) ?? null, setItem: (key, value) => storage.set(key, value), removeItem: (key) => storage.delete(key) };
  const review = { ...state, ...state.review };
  saveInProgressReview(adapter, "key", review);
  const restored = loadInProgressReview(adapter, "key", state.headSha);
  assert.equal(restored.replay.recordingId, "session");
  assert.deepEqual(restored.comments, state.review.comments);
  assert.equal(restored.summary, "Historical note");
});

test("the committed recording is excluded from code diffs without dropping adjacent files", () => {
  const artifact = `diff --git a/${PR_RECORDING_PATH} b/${PR_RECORDING_PATH}\nnew file mode 100644\n--- /dev/null\n+++ b/${PR_RECORDING_PATH}\n@@ -0,0 +1 @@\n+recording content\n`;
  const second = canonicalDiff.replaceAll("math.js", "other.js");
  assert.equal(withoutRecordingDiff(artifact + canonicalDiff), canonicalDiff);
  assert.equal(withoutRecordingDiff(canonicalDiff + artifact + second), canonicalDiff + second);
  assert.equal(withoutRecordingDiff(artifact), "");
});

test("committed-recording downloads enforce byte limits even without a content-length header", async () => {
  assert.equal(await readRecordingResponse(new Response("héllo")), "héllo");
  await assert.rejects(readRecordingResponse(new Response("123456", { headers: { "content-length": "6" } }), 5), /limit/);
  await assert.rejects(readRecordingResponse(new Response("123456"), 5), /limit/);
  await assert.rejects(readRecordingResponse(new Response(new Uint8Array([0xff]))), /encoded|encoding/i);
});

before.content:
import assert from "node:assert/strict";
import test from "node:test";
import { mkdtemp, readFile, writeFile, rm, symlink } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { execFileSync, spawnSync } from "node:child_process";
import { contentHash, parseRecording, recordingStateAt } from "../lib/recording.ts";

const recorder = resolve("scripts/record.mjs");
async function fixture(t) {
  const repo = await mkdtemp(join(tmpdir(), "chronosphere-test-"));
  t.after(() => rm(repo, { recursive: true, force: true }));
  execFileSync("git", ["init", "--quiet", repo]);
  await writeFile(join(repo, ".gitignore"), ".chronosphere/\nignored.txt\n");
  const session = join(repo, ".chronosphere", "test.jsonl");
  function run(...args) {
    const result = spawnSync(process.execPath, ["--experimental-strip-types", recorder, ...args], { cwd: repo, encoding: "utf8" });
    if (result.error) throw result.error;
    return result;
  }
  function okay(...args) {
    const result = run(...args);
    assert.equal(result.status, 0, `${result.stdout}\n${result.stderr}`);
    return result;
  }
  function start(...args) { return okay("start", "--out", session, "--title", "Test session", ...args); }
  function checkpoint(title = "Edit") { return okay("checkpoint", "--session", session, "--title", title, "--reason", "Exercise a recorded change."); }
  const read = async () => parseRecording(await readFile(session, "utf8"));
  return { repo, session, run, okay, start, checkpoint, read };
}

test("recordings preserve dirty baselines, successive edits, additions, deletions, and reversals", async (t) => {
  const f = await fixture(t);
  await writeFile(join(f.repo, "math.js"), "original\n");
  execFileSync("git", ["-C", f.repo, "add", "math.js"]);
  await writeFile(join(f.repo, "math.js"), "dirty baseline\n");
  f.start();
  await writeFile(join(f.repo, "math.js"), "first attempt\n");
  await writeFile(join(f.repo, "temporary.js"), "trial\n");
  f.checkpoint("First attempt");
  await writeFile(join(f.repo, "math.js"), "dirty baseline\n");
  await rm(join(f.repo, "temporary.js"));
  f.checkpoint("Reverse attempt");
  f.okay("finish", "--session", f.session, "--title", "Done", "--reason", "Reverted the trial.");
  const log = await f.read();
  assert.equal(recordingStateAt(log, 0).get("math.js").content, "dirty baseline\n");
  assert.equal(recordingStateAt(log, 1).get("math.js").content, "first attempt\n");
  assert.equal(recordingStateAt(log, 1).get("temporary.js").content, "trial\n");
  assert.equal(recordingStateAt(log, 2).get("math.js").content, "dirty baseline\n");
  assert.equal(recordingStateAt(log, 2).has("temporary.js"), false);
  assert.deepEqual(log.events.map((event) => event.sequence), [1, 2, 3]);
  const closed = f.run("checkpoint", "--session", f.session, "--title", "Late", "--reason", "Too late");
  assert.equal(closed.status, 1);
  assert.match(closed.stderr, /finished/);
});

test("command failures retain output, status, and command-created files, without attributing pending edits", async (t) => {
  const f = await fixture(t);
  f.start();
  await writeFile(join(f.repo, "pending.txt"), "pending");
  const args = ["run", "--session", f.session, "--title", "Failing test", "--reason", "Check the first attempt", "--", process.execPath, "-e", "require('fs').writeFileSync('result.txt', 'failed'); console.log('failure evidence'); process.exit(7)"];
  const blocked = f.run(...args);
  assert.equal(blocked.status, 1);
  assert.match(blocked.stderr, /unrecorded edits/);
  f.checkpoint();
  const failed = f.run(...args);
  assert.equal(failed.status, 7);
  const log = await f.read();
  assert.equal(log.events[1].command.exitCode, 7);
  assert.match(log.events[1].command.output, /failure evidence/);
  assert.deepEqual(log.events[1].changes.map((change) => change.path), ["result.txt"]);
  assert.equal(recordingStateAt(log, 2).get("result.txt").content, "failed");
});

test("scope, ignored files, symlinks, binary data and sensitive names are respected", async (t) => {
  const f = await fixture(t);
  await writeFile(join(f.repo, "safe.txt"), "safe\n");
  await writeFile(join(f.repo, "ignored.txt"), "ignored");
  await writeFile(join(f.repo, ".env"), "SECRET=secret");
  await writeFile(join(f.repo, "binary.bin"), Buffer.from([0, 1, 2]));
  await writeFile(join(f.repo, "large.txt"), "x".repeat(256 * 1024 + 1));
  await symlink(join(f.repo, "safe.txt"), join(f.repo, "linked.txt"));
  f.start();
  let log = await f.read();
  assert.deepEqual(Object.keys(log.session.baseline).sort(), [".gitignore", "safe.txt"]);
  assert.deepEqual(log.session.omitted.map((item) => item.path), [".env", "binary.bin", "large.txt", "linked.txt"]);
  await writeFile(join(f.repo, "safe.txt"), Buffer.from([0, 0]));
  f.checkpoint();
  log = await f.read();
  assert.equal(log.events[0].changes.length, 0);
  assert.equal(log.events[0].omitted.some((item) => item.path === "safe.txt"), true);
  assert.equal(recordingStateAt(log, 1).get("safe.txt").content, "safe\n");
});

test("literal scope supports future files, unicode paths, empty content and renames", async (t) => {
  const f = await fixture(t);
  f.start("--include", "café file.txt", "--include", "renamed.txt");
  await writeFile(join(f.repo, "café file.txt"), "");
  await writeFile(join(f.repo, "outside.txt"), "not in scope");
  f.checkpoint();
  await rm(join(f.repo, "café file.txt"));
  await writeFile(join(f.repo, "renamed.txt"), "");
  f.checkpoint();
  const log = await f.read();
  assert.equal(recordingStateAt(log, 1).get("café file.txt").content, "");
  assert.deepEqual([...recordingStateAt(log, 2).keys()], ["renamed.txt"]);
});

test("imports reject tampering, missing events, broken patch preconditions and incomplete JSON", async (t) => {
  const f = await fixture(t);
  await writeFile(join(f.repo, "file.txt"), "one");
  f.start();
  await writeFile(join(f.repo, "file.txt"), "two"); f.checkpoint();
  await writeFile(join(f.repo, "file.txt"), "three"); f.checkpoint();
  const lines = (await readFile(f.session, "utf8")).trim().split("\n").map(JSON.parse);
  const stringify = (records) => records.map((value) => JSON.stringify(value)).join("\n");
  const tampered = structuredClone(lines);
  tampered[1].changes[0].after.content = "tampered";
  await assert.rejects(parseRecording(stringify(tampered)), /hash/);
  await assert.rejects(parseRecording(stringify([lines[0], lines[2]])), /missing, reordered/);
  const broken = structuredClone(lines);
  broken[2].changes[0].before = { content: "different", sha256: await contentHash("different") };
  await assert.rejects(parseRecording(stringify(broken)), /prior state/);
  await assert.rejects(parseRecording(`${stringify(lines)}\n{"type":`), /incomplete/);
  const path = structuredClone(lines);
  path[1].changes[0].path = "../outside";
  await assert.rejects(parseRecording(stringify(path)), /file path/);
});

test("exclusive locks prevent interleaved appends and existing sessions are never overwritten", async (t) => {
  const f = await fixture(t);
  f.start();
  const source = await readFile(f.session, "utf8");
  assert.equal(f.run("start", "--out", f.session, "--title", "Duplicate").status, 1);
  await writeFile(`${f.session}.lock`, "");
  const locked = f.run("checkpoint", "--session", f.session, "--title", "Concurrent", "--reason", "Test lock");
  assert.equal(locked.status, 1);
  assert.match(locked.stderr, /locked/);
  assert.equal(await readFile(f.session, "utf8"), source);
});

test("commands that cannot start still produce a recorded failure", async (t) => {
  const f = await fixture(t);
  f.start();
  const result = f.run("run", "--session", f.session, "--title", "Unavailable command", "--reason", "Check failure capture", "--", "chronosphere-nonexistent-command-123");
  assert.equal(result.status, 1);
  const log = await f.read();
  assert.equal(log.events[0].command.exitCode, null);
  assert.match(log.events[0].command.output, /Could not start command/);
});

test("a previously captured file that becomes ignored is omitted without reading new content", async (t) => {
  const f = await fixture(t);
  await writeFile(join(f.repo, "local.txt"), "public version");
  f.start();
  await writeFile(join(f.repo, ".gitignore"), ".chronosphere/\nlocal.txt\n");
  await writeFile(join(f.repo, "local.txt"), "private version");
  f.checkpoint();
  const log = await f.read();
  assert.equal(recordingStateAt(log, 1).get("local.txt").content, "public version");
  assert.deepEqual(log.events[0].omitted, [{ path: "local.txt", reason: "Now ignored by Git" }]);
  assert.equal((await readFile(f.session, "utf8")).includes("private version"), false);
});

